                        value={percentageFrom}
                        onChange={(e) => setPercentageFrom(e.target.value)}
                        style={{
                          width: "100%",
                          height: "36px",
                          padding: "0 10px",
                          border: "1px solid var(--border)",
                          borderRadius: "var(--radius-sm)",
                          background: "var(--card)",
                          color: "var(--text)",
                          fontSize: "13px",
                        }}
                      >
                        <option value="Basic Salary">Basic Salary</option>
                        <option value="Gross Wages">Gross Wages</option>
                        <option value="Basic + DA">Basic + DA</option>
                      </select>
                    </div>
                  </div>
                )}

                <div style={{ marginTop: "12px" }}>
                  <label
                    style={{
                      display: "block",
                      fontSize: "12px",
                      fontWeight: 600,
                      color: "var(--text)",
                      marginBottom: "4px",
                    }}
                  >
                    Maximum Statutory Cap (₹) (Optional)
                  </label>
                  <input
                    type="number"
                    placeholder="e.g. 1800 (EPF cap)"
                    value={cap}
                    onChange={(e) => setCap(e.target.value)}
                    style={{
                      width: "100%",
                      height: "36px",
                      padding: "0 10px",
                      border: "1px solid var(--border)",
                      borderRadius: "var(--radius-sm)",
                      background: "var(--card)",
                      color: "var(--text)",
                      fontSize: "13px",
                      fontFamily: "monospace",
