                }}
              >
                {[
                  "Jan",
                  "Feb",
                  "Mar",
                  "Apr",
                  "May",
                  "Jun",
                  "Jul",
                  "Aug",
                  "Sep",
                  "Oct",
                  "Nov",
                  "Dec",
                ].map((m, i) => (
                  <option key={m} value={i + 1}>
                    {m}
                  </option>
                ))}
              </select>
              <select
                value={runYear}
                onChange={(e) => setRunYear(Number(e.target.value))}
                style={{
                  height: "34px",
                  padding: "0 8px",
                  border: "1px solid var(--border)",
                  borderRadius: "var(--radius-sm)",
                  background: "var(--card)",
                  color: "var(--text)",
                  fontSize: "12.5px",
                  fontWeight: 600,
                }}
              >
                {[2024, 2025, 2026, 2027].map((y) => (
                  <option key={y} value={y}>
                    {y}
                  </option>
                ))}
              </select>
            </div>

            {/* Run All Tiers Combined */}
            <button
              onClick={() => handleRunTierPayroll("ALL")}
              disabled={!!runningTier}
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: "5px",
                padding: "7px 14px",
                background: "var(--primary)",
                color: "#fff",
                border: "none",
                borderRadius: "var(--radius-sm)",
                fontSize: "12.5px",
                fontWeight: 700,
                cursor: runningTier ? "not-allowed" : "pointer",
                opacity: runningTier ? 0.7 : 1,
              }}
            >
              <Play size={13} fill="#fff" />
              {runningTier === "ALL" ? "Processing…" : "Run All Tiers Combined"}
            </button>

            {/* Run For Selected Tier Separately */}
            {selectedSkillFilter !== "ALL" && (
              <button
                onClick={() => handleRunTierPayroll(selectedSkillFilter)}
                disabled={!!runningTier}
                style={{
                  display: "inline-flex",
                  alignItems: "center",
                  gap: "5px",
                  padding: "7px 14px",
                  background: "var(--card)",
                  color: "var(--primary)",
                  border: "1px solid var(--primary)",
                  borderRadius: "var(--radius-sm)",
                  fontSize: "12.5px",
                  fontWeight: 700,
                  cursor: runningTier ? "not-allowed" : "pointer",
                  opacity: runningTier ? 0.7 : 1,
                }}
              >
                <Play size={13} />
                {runningTier === selectedSkillFilter
                  ? "Processing…"
                  : `Run ${selectedSkillFilter} Only`}
              </button>
            )}
          </div>
        </div>

        {/* Search & Department Filter Bar */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            flexWrap: "wrap",
            gap: "10px",
            marginBottom: "14px",
            background: "var(--background)",
            padding: "10px 14px",
            borderRadius: "var(--radius)",
            border: "1px solid var(--border)",
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: "10px",
              flexWrap: "wrap",
              flex: 1,
            }}
          >
            {/* Search Input */}
            <div
              style={{
                position: "relative",
                display: "flex",
                alignItems: "center",
                minWidth: "220px",
                maxWidth: "340px",
                flex: 1,
              }}
            >
              <Search
                size={14}
                style={{
                  position: "absolute",
                  left: "10px",
                  color: "var(--subtext)",
                  pointerEvents: "none",
                }}
              />
              <input
                type="text"
                placeholder="Search name, code, designation..."
                value={empSearch}
                onChange={(e) => {
                  setEmpSearch(e.target.value);
                  setEmpPage(1);
                }}
                style={{
                  width: "100%",
                  height: "32px",
                  padding: "0 10px 0 32px",
                  borderRadius: "var(--radius-sm)",
                  border: "1px solid var(--border)",
                  background: "var(--card)",
                  color: "var(--text)",
                  fontSize: "12px",
                }}
              />
              {empSearch && (
                <button
                  onClick={() => {
                    setEmpSearch("");
                    setEmpPage(1);
                  }}
                  style={{
                    position: "absolute",
                    right: "8px",
                    background: "none",
                    border: "none",
                    color: "var(--subtext)",
                    cursor: "pointer",
                    padding: 0,
                  }}
                >
                  <X size={12} />
                </button>
              )}
            </div>

            {/* Department Filter */}
            <div style={{ display: "flex", alignItems: "center", gap: "6px" }}>
              <Filter size={13} style={{ color: "var(--subtext)" }} />
              <select
                value={empDeptFilter}
                onChange={(e) => {
                  setEmpDeptFilter(e.target.value);
                  setEmpPage(1);
                }}
                style={{
                  height: "32px",
                  padding: "0 8px",
                  borderRadius: "var(--radius-sm)",
                  border: "1px solid var(--border)",
                  background: "var(--card)",
                  color: "var(--text)",
                  fontSize: "12px",
                }}
              >
                <option value="ALL">All Departments</option>
                {dynamicDepartments.map((dept) => (
                  <option key={dept} value={dept}>
                    {dept}
                  </option>
                ))}
              </select>
            </div>

            {(empSearch || empDeptFilter !== "ALL") && (
              <button
                onClick={() => {
                  setEmpSearch("");
                  setEmpDeptFilter("ALL");
                  setEmpPage(1);
                }}
                style={{
                  display: "inline-flex",
                  alignItems: "center",
                  gap: "4px",
                  padding: "4px 8px",
                  background: "none",
                  border: "1px dashed var(--border)",
                  borderRadius: "var(--radius-sm)",
                  color: "var(--subtext)",
                  fontSize: "11.5px",
                  cursor: "pointer",
                }}
              >
                <X size={11} /> Reset Filters
              </button>
            )}
          </div>

          <div style={{ fontSize: "12px", color: "var(--subtext)" }}>
            Showing{" "}
            <strong>
              {processedAssociatedEmployees.length === 0
                ? 0
                : (safeEmpPage - 1) * EMP_PAGE_SIZE + 1}
            </strong>
            –
            <strong>
              {Math.min(
                safeEmpPage * EMP_PAGE_SIZE,
                processedAssociatedEmployees.length,
              )}
            </strong>{" "}
            of <strong>{processedAssociatedEmployees.length}</strong> employees
          </div>
        </div>

        {/* Associated Employees Table with Dynamic Earning Component Columns */}
        {processedAssociatedEmployees.length === 0 ? (
          <EmptyState
            title="No employees found"
            subtitle={
              empSearch || empDeptFilter !== "ALL"
                ? "No employees match your current search or department filter."
                : `No active employees are currently assigned to the ${selectedSkillFilter} tier.`
            }
          />
        ) : (
          <div
            style={{
              overflowX: "auto",
              borderRadius: "var(--radius)",
              border: "1px solid var(--border)",
              boxShadow: "var(--shadow-sm)",
              background: "var(--card)",
            }}
          >
            <table
              style={{
                width: "100%",
                borderCollapse: "collapse",
                textAlign: "left",
              }}
            >
              <thead>
                <tr
                  style={{
                    background: "var(--background)",
                    borderBottom: "1px solid var(--border)",
                  }}
                >
                  <th
                    style={{
                      padding: "10px 12px",
                      fontSize: "11px",
                      fontWeight: 700,
                      color: "var(--subtext)",
                      textTransform: "uppercase",
                      letterSpacing: "0.5px",
                      width: "44px",
                    }}
                  >
                    #
                  </th>

                  <th
                    onClick={() => handleEmpSort("name")}
                    style={{
                      padding: "10px 14px",
                      fontSize: "11px",
                      fontWeight: 700,
                      color: "var(--subtext)",
                      textTransform: "uppercase",
                      letterSpacing: "0.5px",
                      cursor: "pointer",
                      userSelect: "none",
                      whiteSpace: "nowrap",
                    }}
                  >
                    <div style={{ display: "inline-flex", alignItems: "center" }}>
                      Employee {renderEmpSortIcon("name")}
                    </div>
                  </th>

                  <th
                    style={{
                      padding: "10px 14px",
                      fontSize: "11px",
                      fontWeight: 700,
                      color: "var(--subtext)",
                      textTransform: "uppercase",
                      letterSpacing: "0.5px",
                      whiteSpace: "nowrap",
                    }}
                  >
                    Designation & Dept
                  </th>

                  <th
                    onClick={() => handleEmpSort("skill")}
                    style={{
                      padding: "10px 14px",
                      fontSize: "11px",
                      fontWeight: 700,
                      color: "var(--subtext)",
                      textTransform: "uppercase",
                      letterSpacing: "0.5px",
                      cursor: "pointer",
                      userSelect: "none",
                      whiteSpace: "nowrap",
                    }}
                  >
                    <div style={{ display: "inline-flex", alignItems: "center" }}>
                      Skill Tier {renderEmpSortIcon("skill")}
                    </div>
                  </th>

                  <th
                    onClick={() => handleEmpSort("rate")}
                    style={{
                      padding: "10px 14px",
                      fontSize: "11px",
                      fontWeight: 700,
                      color: "var(--subtext)",
                      textTransform: "uppercase",
                      letterSpacing: "0.5px",
                      cursor: "pointer",
                      userSelect: "none",
                      whiteSpace: "nowrap",
                    }}
                  >
                    <div style={{ display: "inline-flex", alignItems: "center" }}>
                      Base Pay / Rate {renderEmpSortIcon("rate")}
                    </div>
                  </th>

                  {/* Dynamic Columns for each Active Earning Component — component name only, no subheader */}
                  {activeEarningComponents.map((comp) => (
                    <th
                      key={comp.id}
                      onClick={() => handleEmpSort(`comp_${comp.id}`)}
                      style={{
                        padding: "10px 14px",
                        fontSize: "11px",
                        fontWeight: 700,
                        color: "var(--text)",
                        textTransform: "uppercase",
                        letterSpacing: "0.5px",
                        cursor: "pointer",
                        userSelect: "none",
                        whiteSpace: "nowrap",
                        background: "rgba(13, 148, 136, 0.04)",
                        borderLeft: "1px solid var(--border)",
                      }}
                      title={`Calculation: ${comp.thresholdType === "percentage" ? `${comp.thresholdValue}% of ${comp.percentageFrom || "Basic"}` : `Fixed ₹${comp.thresholdValue}`} | Tier: ${comp.skillType || "ALL"}`}
                    >
                      <div style={{ display: "inline-flex", alignItems: "center", gap: "2px" }}>
                        <span>{comp.name}</span>
                        {renderEmpSortIcon(`comp_${comp.id}`)}
                      </div>
                    </th>
                  ))}


                  <th
                    style={{
                      padding: "10px 14px",
                      fontSize: "11px",
                      fontWeight: 700,
                      color: "var(--primary)",
                      textTransform: "uppercase",
                      letterSpacing: "0.5px",
                      whiteSpace: "nowrap",
                      borderLeft: "1px solid var(--border)",
                    }}
                    title="Sum of all active earning components = Monthly Gross"
                  >
                    Gross Earnings
                  </th>

                  <th
                    style={{
                      padding: "10px 14px",
                      fontSize: "11px",
                      fontWeight: 700,
                      color: "var(--subtext)",
                      textTransform: "uppercase",
                      letterSpacing: "0.5px",
                      whiteSpace: "nowrap",
                    }}
                  >
                    Status
                  </th>
                </tr>
              </thead>
              <tbody>
                {pagedAssociatedEmployees.map((emp, idx) => {
                  const skill = emp.skillType || "Skilled";
                  const isDaily =
                    emp.salaryType === "Daily" ||
                    (Number(emp.dailyWageRate) > 0 && !emp.annualSalary);

                  let rowTotalEarnings = 0;
                  const compValues = activeEarningComponents.map((comp) => {
                    const val = calculateEmployeeComponent(emp, comp, activeEarningComponents);
                    rowTotalEarnings += val;
                    return { comp, val };
                  });
                  // Verify: total should equal monthlyGross (residual approach)
                  const isDaily2 = emp.salaryType === "Daily" || (Number(emp.dailyWageRate) > 0 && !emp.annualSalary);
                  const empMonthlyGross = isDaily2
                    ? Number(emp.dailyWageRate || 750) * 26
                    : Math.round((Number(emp.annualSalary) || 300000) / 12);

                  return (
                    <tr
                      key={emp.id}
                      style={{
                        borderBottom:
                          idx < pagedAssociatedEmployees.length - 1
                            ? "1px solid var(--border)"
                            : "none",
                        transition: "background 0.15s ease",
                      }}
                      onMouseEnter={(e) =>
                        (e.currentTarget.style.background =
                          "var(--hover-bg, rgba(0,0,0,0.015))")
                      }
                      onMouseLeave={(e) =>
                        (e.currentTarget.style.background = "transparent")
                      }
                    >
                      <td
                        style={{
                          padding: "10px 12px",
                          fontSize: "12px",
                          color: "var(--subtext)",
                          fontFamily: "monospace",
                        }}
                      >
                        {(safeEmpPage - 1) * EMP_PAGE_SIZE + idx + 1}
                      </td>

                      <td style={{ padding: "10px 14px", whiteSpace: "nowrap" }}>
                        <div
                          style={{
                            fontWeight: 700,
                            color: "var(--text)",
                            fontSize: "13px",
                          }}
                        >
                          {emp.firstName} {emp.lastName}
                        </div>
                        <div
                          style={{
                            fontSize: "11.5px",
                            color: "var(--subtext)",
                            fontFamily: "monospace",
                          }}
                        >
                          {emp.employeeCode || emp.id}
                        </div>
                      </td>

                      <td style={{ padding: "10px 14px", whiteSpace: "nowrap" }}>
                        <div
                          style={{
                            fontSize: "12.5px",
                            color: "var(--text)",
                            fontWeight: 500,
                          }}
                        >
                          {emp.designation?.title ||
                            emp.designation ||
                            "Staff"}
                        </div>
                        <div
                          style={{ fontSize: "11px", color: "var(--subtext)" }}
                        >
                          {emp.department?.name || emp.department || "General"}
                        </div>
                      </td>

                      <td style={{ padding: "10px 14px", whiteSpace: "nowrap" }}>
                        <span
                          style={{
                            fontSize: "11px",
                            fontWeight: 700,
                            padding: "2px 8px",
                            borderRadius: "99px",
                            background: skill.toLowerCase().includes("semi")
                              ? "#eff6ff"
                              : skill.toLowerCase().includes("unskilled")
                              ? "#f8fafc"
                              : "#ecfdf5",
                            color: skill.toLowerCase().includes("semi")
                              ? "#2563eb"
                              : skill.toLowerCase().includes("unskilled")
                              ? "#64748b"
                              : "#059669",
                            border: `1px solid ${
                              skill.toLowerCase().includes("semi")
                                ? "#bfdbfe"
                                : skill.toLowerCase().includes("unskilled")
                                ? "#e2e8f0"
                                : "#a7f3d0"
                            }`,
                          }}
                        >
                          {skill}
                        </span>
                      </td>

                      <td
                        style={{
                          padding: "10px 14px",
                          fontSize: "12.5px",
                          fontFamily: "monospace",
                          whiteSpace: "nowrap",
                        }}
                      >
                        {isDaily ? (
                          <span style={{ color: "#0284c7", fontWeight: 700 }}>
                            ₹
                            {Number(emp.dailyWageRate || 750).toLocaleString(
                              "en-IN",
                            )}
                            /day
                          </span>
                        ) : (
                          <span
                            style={{ color: "var(--text)", fontWeight: 700 }}
                          >
                            ₹
                            {Math.round(
                              (Number(emp.annualSalary) || 300000) / 12,
                            ).toLocaleString("en-IN")}
                            /mo
                          </span>
                        )}
                      </td>

                      {/* Dynamic Component Values for this Employee */}
                      {compValues.map(({ comp, val }) => (
                        <td
                          key={comp.id}
                          style={{
                            padding: "10px 14px",
                            fontSize: "12.5px",
                            fontFamily: "monospace",
                            whiteSpace: "nowrap",
                            borderLeft: "1px solid var(--border)",
                            background: "rgba(13, 148, 136, 0.015)",
                            color: val > 0 ? "var(--text)" : "var(--subtext)",
                            fontWeight: val > 0 ? 600 : 400,
                          }}
                        >
                          {val > 0 ? (
                            `₹${val.toLocaleString("en-IN")}`
                          ) : (
                            <span style={{ opacity: 0.4 }}>—</span>
                          )}
                        </td>
                      ))}

                      <td
                        style={{
                          padding: "10px 14px",
                          fontSize: "13px",
                          fontFamily: "monospace",
                          fontWeight: 700,
                          color: Math.abs(rowTotalEarnings - empMonthlyGross) <= 5 ? "#059669" : "var(--primary)",
                          whiteSpace: "nowrap",
                          borderLeft: "1px solid var(--border)",
                          background: Math.abs(rowTotalEarnings - empMonthlyGross) <= 5
                            ? "rgba(5,150,105,0.04)"
                            : "transparent",
                        }}
                        title={Math.abs(rowTotalEarnings - empMonthlyGross) <= 5
                          ? "✓ Matches monthly gross"
                          : `Note: ${rowTotalEarnings > empMonthlyGross ? 'Exceeds' : 'Below'} monthly gross by ₹${Math.abs(rowTotalEarnings - empMonthlyGross).toLocaleString('en-IN')}`}
                      >
                        ₹{rowTotalEarnings.toLocaleString("en-IN")}
                      </td>

                      <td style={{ padding: "10px 14px", whiteSpace: "nowrap" }}>
                        <span
                          style={{
                            fontSize: "11px",
                            fontWeight: 700,
                            padding: "2px 8px",
                            borderRadius: "99px",
                            background: "#f0fdf4",
                            color: "#16a34a",
                            border: "1px solid #bbf7d0",
                          }}
                        >
                          {emp.status || "Active"}
                        </span>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}

        {/* Strictly 10 per page pagination bar */}
        {processedAssociatedEmployees.length > EMP_PAGE_SIZE && (
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              flexWrap: "wrap",
              gap: "12px",
              marginTop: "16px",
              padding: "12px 16px",
              background: "var(--background)",
              borderRadius: "var(--radius)",
              border: "1px solid var(--border)",
            }}
          >
            <div style={{ fontSize: "12.5px", color: "var(--subtext)" }}>
              Showing{" "}
              <strong>{(safeEmpPage - 1) * EMP_PAGE_SIZE + 1}</strong>
              –
              <strong>
                {Math.min(
                  safeEmpPage * EMP_PAGE_SIZE,
                  processedAssociatedEmployees.length,
                )}
              </strong>{" "}
              of <strong>{processedAssociatedEmployees.length}</strong> employees
              (Page {safeEmpPage} of {empPageCount})
            </div>

            <div style={{ display: "flex", alignItems: "center", gap: "6px" }}>
              <button
                onClick={() => setEmpPage((p) => Math.max(1, p - 1))}
                disabled={safeEmpPage <= 1}
                style={{
                  display: "inline-flex",
                  alignItems: "center",
                  gap: "4px",
                  padding: "5px 12px",
                  borderRadius: "var(--radius-sm)",
                  border: "1px solid var(--border)",
                  background: "var(--card)",
                  color: safeEmpPage <= 1 ? "var(--subtext)" : "var(--text)",
                  fontSize: "12.5px",
                  fontWeight: 600,
                  cursor: safeEmpPage <= 1 ? "not-allowed" : "pointer",
                  opacity: safeEmpPage <= 1 ? 0.5 : 1,
                }}
              >
                <ChevronLeft size={14} /> Previous
              </button>

              {Array.from({ length: empPageCount }, (_, i) => i + 1).map((pg) => {
                const isCurrent = pg === safeEmpPage;
                if (
                  empPageCount > 7 &&
                  pg !== 1 &&
                  pg !== empPageCount &&
                  Math.abs(pg - safeEmpPage) > 1
                ) {
                  if (pg === 2 || pg === empPageCount - 1) {
                    return (
                      <span
                        key={`dots-${pg}`}
                        style={{ padding: "0 4px", color: "var(--subtext)" }}
                      >
                        …
                      </span>
                    );
                  }
                  return null;
                }
                return (
                  <button
                    key={pg}
                    onClick={() => setEmpPage(pg)}
                    style={{
                      minWidth: "30px",
                      height: "30px",
                      padding: "0 6px",
                      borderRadius: "var(--radius-sm)",
                      border: isCurrent
                        ? "1px solid var(--primary)"
                        : "1px solid var(--border)",
                      background: isCurrent ? "var(--primary)" : "var(--card)",
                      color: isCurrent ? "#fff" : "var(--text)",
                      fontSize: "12.5px",
                      fontWeight: isCurrent ? 700 : 500,
                      cursor: "pointer",
                    }}
                  >
                    {pg}
                  </button>
                );
              })}

              <button
                onClick={() => setEmpPage((p) => Math.min(empPageCount, p + 1))}
                disabled={safeEmpPage >= empPageCount}
                style={{
                  display: "inline-flex",
                  alignItems: "center",
                  gap: "4px",
                  padding: "5px 12px",
                  borderRadius: "var(--radius-sm)",
                  border: "1px solid var(--border)",
                  background: "var(--card)",
                  color:
                    safeEmpPage >= empPageCount
                      ? "var(--subtext)"
                      : "var(--text)",
                  fontSize: "12.5px",
                  fontWeight: 600,
                  cursor:
                    safeEmpPage >= empPageCount ? "not-allowed" : "pointer",
                  opacity: safeEmpPage >= empPageCount ? 0.5 : 1,
                }}
              >
                Next <ChevronRight size={14} />
              </button>
            </div>
          </div>
        )}
      </div>

    </section>
  );
}

