                    <select
                      value={calcType}
                      onChange={(e) => setCalcType(e.target.value)}
                      style={{
                        width: "100%",
                        height: "36px",
                        padding: "0 10px",
                        border: "1px solid var(--border)",
                        borderRadius: "var(--radius-sm)",
                        background: "var(--background)",
                        color: "var(--text)",
