                      : "0"}
                  </div>
                </div>
              </div>

              <div>
                <label
                  style={{
                    display: "block",
                    fontSize: "12px",
                    fontWeight: 700,
                    color: "var(--text)",
                    marginBottom: "4px",
                  }}
                >
                  Hourly Wage Rate (₹) (Optional)
                </label>
                <input
                  type="number"
                  placeholder="Derived automatically (Daily / 8)"
                  value={formHourlyRate}
                  onChange={(e) => setFormHourlyRate(e.target.value)}
                  style={{
                    width: "100%",
                    height: "38px",
                    padding: "0 10px",
                    border: "1px solid var(--border)",
                    borderRadius: "var(--radius-sm)",
                    background: "var(--background)",
                    color: "var(--text)",
                    fontSize: "13.5px",
                    fontFamily: "monospace",
                  }}
                />
              </div>

              <div>
                <label
                  style={{
                    display: "block",
                    fontSize: "12px",
                    fontWeight: 700,
                    color: "var(--text)",
                    marginBottom: "4px",
                  }}
                >
                  Branch / Site Specific Override (Optional)
                </label>
                <select
                  value={formLocationId}
                  onChange={(e) => setFormLocationId(e.target.value)}
                  style={{
                    width: "100%",
                    height: "38px",
                    padding: "0 10px",
                    border: "1px solid var(--border)",
                    borderRadius: "var(--radius-sm)",
                    background: "var(--background)",
                    color: "var(--text)",
                    fontSize: "13.5px",
                  }}
                >
                  <option value="">All Branches within State</option>
                  {locations.map((loc) => (
                    <option key={loc.id} value={loc.id}>
                      {loc.name}
                    </option>
                  ))}
                </select>
              </div>

              <div
                style={{
                  display: "flex",
                  justifyContent: "flex-end",
                  gap: "10px",
                  marginTop: "10px",
                }}
              >
                <button
                  type="button"
                  onClick={() => setShowAddModal(false)}
                  style={{
                    padding: "8px 16px",
                    background: "var(--background)",
                    color: "var(--text)",
                    border: "1px solid var(--border)",
                    borderRadius: "var(--radius-sm)",
                    fontSize: "13px",
                    fontWeight: 600,
                    cursor: "pointer",
                  }}
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={saving}
                  style={{
                    padding: "8px 18px",
                    background: "var(--primary)",
                    color: "#fff",
                    border: "none",
                    borderRadius: "var(--radius-sm)",
                    fontSize: "13px",
                    fontWeight: 600,
                    cursor: "pointer",
                  }}
                >
                  {saving ? "Saving…" : "Save Wage Rate"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

    </section>
  );
}

/**
 * ClassicTablePayslip — Client Focus Style
 * Pixel-perfect implementation of the Client Focus Classic Table payslip layout
 * with customizable logo placement, dynamic logo sizing, serif typography,
 * attendance & salary breakdown tables, and custom color accents.
 */

import React from "react";
import { assetUrl } from "../../utils/assetUrl.js";
import { inr } from "../../utils/currency.js";
import { rupeesInWords } from "../../utils/numberToWords.js";

export default function ClassicTablePayslip({
  company = {},
  logoSize = 170,
  employee = {},
  payroll = {},
  theme = {
    primaryColor: "#3478d4",
    accentColor: "#1f7a32",
    tableBorderColor: "#111111",
  },
  visibility = {
    info: true,
    attendance: true,
