        </div>
        <div style={{ font: "10px Inter, Arial, sans-serif", color: "#9aa6b5", marginTop: "5px" }}>
          Company Logo
        </div>
      </div>

      {/* ── COMPANY HEADER ── */}
      <div style={{ textAlign: "center", paddingTop: "100px" }}>
        <h1
          style={{
            font: '700 24px Georgia, "Times New Roman", serif',
