function fmt(v) {
  if (v == null || v === "") return "—";
  if (v instanceof Date || (typeof v === "string" && /^\d{4}-\d{2}-\d{2}T/.test(v))) return new Date(v).toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" });
  return String(v);
}

export default function EmployeeProfile() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { role } = useAuth();
  const [employee, setEmployee] = useState(null);
  const [local, setLocal] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [activeTab, setActiveTab] = useState("identity");
  const [editing, setEditing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState("");
  const [errMsg, setErrMsg] = useState("");
  const [addConsentOpen, setAddConsentOpen] = useState(false);
  const [consentDraft, setConsentDraft] = useState({ code: "", title: "", purposeText: "", legalBasis: "CONTRACT", isStatutory: false });
  const [creatingConsent, setCreatingConsent] = useState(false);
  // Dynamic payroll component options fetched from the database
  const [dynamicEarnings, setDynamicEarnings] = useState([]);
  const [dynamicDeductions, setDynamicDeductions] = useState([]);

  // Fetch dynamic payroll components once on mount
  useEffect(() => {
    getPayrollComponentConfigs().catch(() => ({ data: [] })).then((res) => {
      const all = res.data || [];
      setDynamicEarnings(all.filter((c) => c.kind !== "deduction").map((c) => c.code || c.name));
      setDynamicDeductions(all.filter((c) => c.kind === "deduction").map((c) => c.code || c.name));
    });
  }, []);

  // Derived: earning/deduction option arrays (fall back to static if API returns nothing)
  const earningsOptions = dynamicEarnings.length > 0 ? dynamicEarnings : ["BASIC", "HRA", "SPECIAL_ALLOWANCE", "TRANSPORT_ALLOWANCE"];
  const deductionsOptions = dynamicDeductions.length > 0 ? dynamicDeductions : ["EPF", "ESIC", "PT", "TDS", "LWF"];

  useEffect(() => {
    getEmployee(id)
      .then((res) => {
        setEmployee(res.data);
        setLocal(buildLocal(res.data?.wizardData, res.data ?? {}));
      })
      .catch((e) => setError(e.message))
      .finally(() => setLoading(false));
  }, [id]);

  const wz = useMemo(() => (employee?.wizardData && typeof employee.wizardData === "object" ? employee.wizardData : null), [employee]);

  const setL = (path, value) => setLocal((p) => setAt(p, path, value));
  const enterEdit = () => { setEditing(true); setErrMsg(""); };
  const cancelEdit = () => { setLocal(buildLocal(employee?.wizardData, employee ?? {})); setEditing(false); setErrMsg(""); };

  const save = async () => {
    setSaving(true);
    setErrMsg("");
    try {
      const flat = {};
      if (local.job.designationTitle && local.job.designationTitle !== (employee.designation || "")) flat.designation = local.job.designationTitle;
      if (local.job.departmentTitle && local.job.departmentTitle !== (employee.department || "")) flat.department = local.job.departmentTitle;
      if (local.job.status && local.job.status !== (employee.status || "")) flat.status = local.job.status;
      if (local.annualSalary !== "" && local.annualSalary != null) flat.annualSalary = Math.round(Number(local.annualSalary));
      const payload = { ...flat, wizardData: local };
      await updateEmployee(id, payload);

      // Dynamically sync production target with payroll production engine
      if (local.payRules?.productionTarget && id) {
        try {
          const now = new Date();
          await createProductionRecord({
            employeeId: id,
            month: now.getMonth() + 1,
            year: now.getFullYear(),
            unitsProduced: 0,
            targetUnits: Number(local.payRules.productionTarget),
            remarks: `Dynamic target calibration (${local.payRules.productionTarget} units/mo)`
          });
        } catch {
          // Non-blocking sync
        }
      }

      const res = await getEmployee(id);
      setEmployee(res.data);
      setLocal(buildLocal(res.data?.wizardData, res.data ?? {}));
      setEditing(false);
      setSaved("Saved successfully");
      setTimeout(() => setSaved(""), 2500);
    } catch (e) {
      setErrMsg(e.message || "Save failed");
    } finally {
      setSaving(false);
    }
  };

  const submitConsentDraft = async () => {
    if (!consentDraft.code.trim() || !consentDraft.title.trim()) return;
    setCreatingConsent(true);
    setErrMsg("");
    try {
      const payload = {
        code: consentDraft.code.trim().toUpperCase(),
        title: consentDraft.title.trim(),
        purposeText: consentDraft.purposeText?.trim() || "",
        legalBasis: consentDraft.legalBasis || "CONTRACT",
        isStatutory: !!consentDraft.isStatutory,
        blocking: !!consentDraft.isStatutory,
        withdrawable: !consentDraft.isStatutory,
        requiredOnOnboarding: false,
        useCase: "EMPLOYEE_PROFILE",
        dataFields: [],
        validityPeriodDays: null,
      };
      await createConsentPolicy(payload);
      // Reflect the newly registered consent type in the register immediately.
      setLocal((p) => ({
        ...p,
        consents: [
          ...(p?.consents || []),
          { code: payload.code, method: "HR_ADMIN", status: "GRANTED" },
        ],
      }));
      setConsentDraft({ code: "", title: "", purposeText: "", legalBasis: "CONTRACT", isStatutory: false });
      setAddConsentOpen(false);
      setSaved("Consent type added");
      setTimeout(() => setSaved(""), 2500);
    } catch (e) {
      setErrMsg(e?.response?.data?.message || e?.message || "Could not add consent type");
    } finally {
      setCreatingConsent(false);
    }
  };

  if (loading) return <MainLayout><Spinner /></MainLayout>;
  if (error) return (
    <MainLayout>
      <div style={{ padding: "40px", textAlign: "center" }}>
        <p style={{ color: "var(--red)", fontWeight: 600 }}>{error}</p>
        <button onClick={() => navigate("/employees")} style={{ marginTop: "16px", padding: "9px 20px", background: "var(--primary)", color: "#fff", border: "none", borderRadius: "var(--radius-sm)", cursor: "pointer", fontWeight: 600 }}>
          Back to Employees
        </button>
      </div>
    </MainLayout>
  );

  const approvedCount = (local?.consents || []).filter((c) => c.status === "GRANTED").length;
  const consentTotal = Math.max((local?.consents || []).length, wz?.consents?.length || 0);

  return (
    <MainLayout>
      <div style={{ maxWidth: "1020px", margin: "0 auto" }}>
        <button
          onClick={() => navigate("/employees")}
          style={{ display: "flex", alignItems: "center", gap: "6px", background: "none", border: "none", cursor: "pointer", color: "var(--subtext)", fontSize: "13.5px", fontWeight: 500, marginBottom: "20px", padding: 0 }}
        >
          <ArrowLeft size={16} /> Back to Employees
        </button>

        <div
          style={{
            background: "linear-gradient(135deg, rgba(99,102,241,0.08), rgba(99,102,241,0.02) 45%, transparent), var(--card)",
            borderRadius: "22px", border: "1px solid var(--border)",
            boxShadow: "0 10px 34px rgba(15,23,42,0.08)", padding: "30px", display: "flex", gap: "22px",
            alignItems: "center", marginBottom: "22px", flexWrap: "wrap", position: "relative", overflow: "hidden",
          }}
        >
          <span style={{ position: "absolute", right: "-70px", top: "-70px", width: "190px", height: "190px", borderRadius: "50%", background: "radial-gradient(circle, rgba(99,102,241,0.16), transparent 70%)", pointerEvents: "none" }} />
          <div style={{ padding: "5px", background: "#fff", borderRadius: "50%", boxShadow: "0 0 0 4px var(--primary-light), 0 8px 20px rgba(0,0,0,0.10)" }}>
            <InitialsAvatar firstName={employee.firstName} lastName={employee.lastName} size={86} borderWidth={3} />
          </div>
          <div style={{ flex: 1, minWidth: 0 }}>
            <p style={{ fontSize: "10.5px", fontWeight: 700, color: "var(--primary)", textTransform: "uppercase", letterSpacing: "1.4px", marginBottom: "4px" }}>Employee Profile</p>
            <div style={{ display: "flex", gap: "12px", alignItems: "center", flexWrap: "wrap", marginBottom: "6px" }}>
              <h1 style={{ fontSize: "24px", fontWeight: 800, color: "var(--text)", letterSpacing: "-0.3px", margin: 0 }}>{employee.firstName} {employee.lastName}</h1>
              <StatusBadge {...(EMPLOYEE_STATUS_META[employee.status] || EMPLOYEE_STATUS_META.Active)} />
            </div>
            <p style={{ fontSize: "14px", color: "var(--subtext)", marginBottom: "4px" }}>{employee.designation || "-"}</p>
            <p style={{ fontSize: "12.5px", color: "var(--label)" }}>{employee.department || "-"} · {employee.id}</p>
            {wz && (
              <p style={{ fontSize: "12px", color: "#16a34a", marginTop: "10px", display: "inline-flex", alignItems: "center", gap: "6px", background: "rgba(22,163,74,0.08)", padding: "5px 10px", borderRadius: "999px", fontWeight: 600 }}>
                <CircleCheck size={13} /> Registration snapshot available · editable
              </p>
            )}
          </div>
          <div style={{ display: "flex", gap: "8px", alignItems: "center" }}>
            {saved && <span style={{ color: "var(--green)", fontWeight: 600, fontSize: "13px" }}>{saved}</span>}
            {errMsg && <span style={{ color: "var(--red)", fontWeight: 600, fontSize: "13px" }}>{errMsg}</span>}
            {editing ? (
              <>
                <button onClick={cancelEdit} disabled={saving} style={ghostBtn}><X size={15} /> Cancel</button>
                <button onClick={save} disabled={saving} style={primaryBtn}><Save size={15} /> {saving ? "Saving…" : "Save tab"}</button>
              </>
            ) : (
              <button onClick={enterEdit} style={primaryBtn}><Pencil size={15} /> Edit</button>
            )}
          </div>
        </div>

        <div style={{ display: "inline-flex", gap: "3px", borderRadius: "16px", background: "var(--background)", border: "1px solid var(--border)", padding: "6px", flexWrap: "nowrap", overflowX: "auto", maxWidth: "100%", marginBottom: "20px", scrollbarWidth: "thin" }}>
          {TABS.map((tab) => {
            const Icon = tab.icon;
            const active = activeTab === tab.id;
            return (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                style={{
                  padding: "9px 15px", border: "none", borderRadius: "11px", cursor: "pointer",
                  background: active ? "#ffffff" : "transparent", whiteSpace: "nowrap",
                  color: active ? "var(--primary)" : "var(--subtext)",
                  fontWeight: active ? 700 : 600, fontSize: "12.5px",
                  display: "inline-flex", alignItems: "center", gap: "6px",
                  boxShadow: active ? "0 2px 8px rgba(0,0,0,0.10)" : "none",
                }}
              >
                <Icon size={14} /> {tab.label}
              </button>
            );
          })}
        </div>

        <EditCtx.Provider value={editing}>
        <div style={{ background: "var(--card)", borderRadius: "22px", border: "1px solid var(--border)", boxShadow: "0 6px 22px rgba(15,23,42,0.06)", padding: "32px", minHeight: "320px" }}>

          {activeTab === "identity" && (
            <>
              <Section title="Identity">
                <Grid editing={editing}>
                  <Input label="Employee code" value={local.employeeCode} onChange={(v) => setL("employeeCode", v)} />
                  <Input label="First name" value={local.firstName} onChange={(v) => setL("firstName", v)} />
                  <Input label="Middle name" value={local.middleName} onChange={(v) => setL("middleName", v)} />
                  <Input label="Last name" value={local.lastName} onChange={(v) => setL("lastName", v)} />
                  <Input label="Date of birth" type="date" value={local.dateOfBirth || undefined} onChange={(v) => setL("dateOfBirth", v)} />
                  <SelectInput label="Gender" value={local.gender} onChange={(v) => setL("gender", v)} options={GENDERS} />
                  <SelectInput label="Marital status" value={local.maritalStatus} onChange={(v) => setL("maritalStatus", v)} options={MARITAL} />
                  <Input label="Nationality" value={local.nationality} onChange={(v) => setL("nationality", v)} />
                  <Input label="Country" value={local.country} onChange={(v) => setL("country", v)} />
                  <Input label="PAN" value={local.pan} onChange={(v) => setL("pan", v)} />
                  <Input label="Aadhaar" value={local.aadhaar} onChange={(v) => setL("aadhaar", v)} />
                  <Input label="Passport number" value={local.passportNumber} onChange={(v) => setL("passportNumber", v)} />
                  <Input label="Passport expiry" type="date" value={local.passportExpiry || undefined} onChange={(v) => setL("passportExpiry", v)} />
                  {!editing &&
                    <>
                      <InfoRow icon={Mail} label="Email" value={local.personalEmail || employee.email} />
                      <InfoRow icon={Phone} label="Mobile" value={local.personalMobile || employee.phone} />
                    </>
                  }
                </Grid>
              </Section>
              <Section title="Contact & emergency">
                <Grid editing={editing}>
                  <Input label="Personal mobile" value={local.personalMobile} onChange={(v) => setL("personalMobile", v)} />
                  <Input label="Personal email" value={local.personalEmail} onChange={(v) => setL("personalEmail", v)} />
                  <Input label="Official email" value={local.officialEmail} onChange={(v) => setL("officialEmail", v)} />
                  <Input label="Official mobile" value={local.officialMobile} onChange={(v) => setL("officialMobile", v)} />
                  <Input label="Emergency contact" value={local.emergencyContactName} onChange={(v) => setL("emergencyContactName", v)} />
                  <Input label="Emergency number" value={local.emergencyContactNumber} onChange={(v) => setL("emergencyContactNumber", v)} />
                  {!editing && <InfoRow icon={Users} label="Emergency relation" value={local.emergencyContactRelation} />}
                  {editing && <Input label="Emergency relation" value={local.emergencyContactRelation} onChange={(v) => setL("emergencyContactRelation", v)} />}
                </Grid>
              </Section>
              <Section title="Addresses">
                {["currentAddress", "permanentAddress"].map((addrKey) => (
                  <div key={addrKey} style={{ marginBottom: "14px" }}>
                    <p style={{ fontSize: "12.5px", fontWeight: 700, color: "var(--subtext)", textTransform: "uppercase", letterSpacing: "0.4px", marginBottom: "8px" }}>
                      {addrKey === "currentAddress" ? "Current address" : "Permanent address"}
                    </p>
                    <Grid editing={editing}>
                      <Input label="Address line 1" value={local[addrKey].line1} onChange={(v) => setL(`${addrKey}.line1`, v)} />
                      <Input label="Address line 2" value={local[addrKey].line2} onChange={(v) => setL(`${addrKey}.line2`, v)} />
                      <Input label="City" value={local[addrKey].city} onChange={(v) => setL(`${addrKey}.city`, v)} />
                      <Input label="State" value={local[addrKey].stateCode} onChange={(v) => setL(`${addrKey}.stateCode`, v)} />
                      <Input label="Pincode" value={local[addrKey].pincode} onChange={(v) => setL(`${addrKey}.pincode`, v)} />
                      <Input label="Country code" value={local[addrKey].countryCode} onChange={(v) => setL(`${addrKey}.countryCode`, v)} />
                      <Input label="Proof type" value={local[addrKey].proofType} onChange={(v) => setL(`${addrKey}.proofType`, v)} />
                    </Grid>
                  </div>
                ))}
              </Section>
            </>
          )}

          {activeTab === "employment" && (
            <Section title="Organization & employment">
              <Grid editing={editing}>
                <Input label="Designation" value={local.job.designationTitle || employee.designation} onChange={(v) => setL("job.designationTitle", v)} />
                <Input label="Department" value={local.job.departmentTitle || employee.department} onChange={(v) => setL("job.departmentTitle", v)} />
                <SelectInput label="Employment type" value={local.job.employmentType} onChange={(v) => setL("job.employmentType", v)} options={EMP_TYPES} />
                <SelectInput label="Employee category" value={local.job.employeeCategory} onChange={(v) => setL("job.employeeCategory", v)} options={EMP_CATS} />
                <SelectInput label="Skill type" value={local.job.skillType} onChange={(v) => setL("job.skillType", v)} options={SKILL_TYPES} />
                <Input label="Date of joining" type="date" value={local.job.dateOfJoining || undefined} onChange={(v) => setL("job.dateOfJoining", v)} />
                <Input label="Confirmation date" type="date" value={local.job.confirmationDate || undefined} onChange={(v) => setL("job.confirmationDate", v)} />
                <Input label="Probation (months)" type="number" value={local.job.probationMonths || ""} onChange={(v) => setL("job.probationMonths", v === "" ? "" : Number(v))} />
                <SelectInput label="Status" value={local.job.status} onChange={(v) => setL("job.status", v)} options={DISPLAY_STATUSES} />
                <SelectInput label="Location type" value={local.job.workLocationType} onChange={(v) => setL("job.workLocationType", v)} options={LOC_TYPES} />
                <Input label="Sub-department" value={local.job.subDepartment} onChange={(v) => setL("job.subDepartment", v)} />
                <Input label="Business unit" value={local.job.businessUnit} onChange={(v) => setL("job.businessUnit", v)} />
                <Input label="Attendance mode" value={local.job.attendanceTrackingMode} onChange={(v) => setL("job.attendanceTrackingMode", v)} />
                <Input label="Notice period (days)" type="number" value={local.job.noticePeriodDays || ""} onChange={(v) => setL("job.noticePeriodDays", v === "" ? "" : Number(v))} />
                <Input label="Weekly offs (comma separated)" value={(local.job.weeklyOffs || []).join(", ")} onChange={(v) => setL("job.weeklyOffs", v.split(",").map((s) => s.trim()).filter(Boolean))} />
                {!editing && (
                  <>
                    <InfoRow icon={MapPin} label="Work location" value={employee.location} />
                    <InfoRow icon={Building2} label="Grade" value={local.job.gradeId} />
                  </>
                )}
              </Grid>
            </Section>
          )}

          {activeTab === "statutory" && (
            <>
              <Section title="Statutory & tax">
                <Grid editing={editing}>
                  <Input label="UAN" value={local.statutory.uanNumber} onChange={(v) => setL("statutory.uanNumber", v)} />
                  <Input label="PF member ID" value={local.statutory.pfNumber} onChange={(v) => setL("statutory.pfNumber", v)} />
                  <SelectInput label="PF applicable" value={String(local.statutory.pfApplicable)} onChange={(v) => setL("statutory.pfApplicable", v === "true")} options={["true", "false"]} />
                  <Input label="PF joining date" type="date" value={local.statutory.pfJoiningDate || undefined} onChange={(v) => setL("statutory.pfJoiningDate", v)} />
                  <Input label="ESI number" value={local.statutory.esicNumber} onChange={(v) => setL("statutory.esicNumber", v)} />
                  <SelectInput label="ESI applicable" value={String(local.statutory.esiApplicable)} onChange={(v) => setL("statutory.esiApplicable", v === "true")} options={["true", "false"]} />
                  <Input label="PT state" value={local.statutory.ptState} onChange={(v) => setL("statutory.ptState", v)} />
                  <SelectInput label="Tax regime" value={local.statutory.taxRegime} onChange={(v) => setL("statutory.taxRegime", v)} options={REGIMES} />
                  <Input label="Tax declaration" value={local.statutory.taxDeclarationStatus} onChange={(v) => setL("statutory.taxDeclarationStatus", v)} />
                </Grid>
              </Section>
              <Section title="Compensation">
                <Grid editing={editing}>
                  <Input label="Yearly salary package (₹)" type="number" value={local.annualSalary || ""} onChange={(v) => { const n = v === "" ? "" : Math.round(Number(v)); setL("annualSalary", n); setL("statutory.annualSalary", n === "" ? "" : Number(n)); setL("monthlyGross", n === "" ? "" : Math.round(Number(n) / 12)); }} />
                  <Input label="Monthly gross (₹)" type="number" value={local.monthlyGross || ""} onChange={(v) => { const n = v === "" ? "" : Math.round(Number(v)); setL("monthlyGross", n); const y = n === "" ? "" : n * 12; setL("annualSalary", y); setL("statutory.annualSalary", y === "" ? "" : y); }} />
                </Grid>
              </Section>
              <Section title="Bank & payment">
                <Grid editing={editing}>
                  <Input label="Bank name" value={local.bank.bankName} onChange={(v) => setL("bank.bankName", v)} />
                  <Input label="Account number" value={local.bank.accountNumber} onChange={(v) => setL("bank.accountNumber", v)} />
                  <Input label="IFSC" value={local.bank.ifscCode} onChange={(v) => setL("bank.ifscCode", v)} />
                  <Input label="Branch" value={local.bank.bankBranch} onChange={(v) => setL("bank.bankBranch", v)} />
                  <Input label="Account holder" value={local.bank.accountHolderName} onChange={(v) => setL("bank.accountHolderName", v)} />
                  <Input label="Account type" value={local.bank.accountType} onChange={(v) => setL("bank.accountType", v)} />
                  <Input label="Salary payment mode" value={local.bank.salaryPaymentMode} onChange={(v) => setL("bank.salaryPaymentMode", v)} />
                  <Input label="UPI ID" value={local.bank.upiId} onChange={(v) => setL("bank.upiId", v)} />
                </Grid>
              </Section>
              <Section title="Production Targets & Factory Output">
                <Grid editing={editing}>
                  <Input label="Monthly production target (Units)" type="number" placeholder="e.g. 1000" value={local.payRules.productionTarget || ""} onChange={(v) => setL("payRules.productionTarget", v === "" ? "" : Number(v))} />
                  <SelectInput label="Assigned contractor / vendor" value={local.payRules.contractor} onChange={(v) => setL("payRules.contractor", v)} options={["Direct Company Worker", ...CONTRACTORS]} />
                  <SelectInput label="Wage rate mode" value={local.payRules.wageRate} onChange={(v) => setL("payRules.wageRate", v)} options={WAGE_RATES} />
                  <Toggle label="Salary advance eligible" value={local.payRules.salaryAdvance} onChange={(v) => setL("payRules.salaryAdvance", v)} />
                  <MultiSelect label="Applicable earning allowances" value={local.payRules.earnings} onChange={(v) => setL("payRules.earnings", v)} options={earningsOptions} />
                  <MultiSelect label="Applicable deductions" value={local.payRules.deductions} onChange={(v) => setL("payRules.deductions", v)} options={deductionsOptions} />
                </Grid>
              </Section>
            </>
          )}

          {activeTab === "family" && (
            <>
              <Section title="Family / nominees / dependents">
                {editing && (
                  <button
                    onClick={() => setL("family", [...(local.family || []), { memberName: "", relationship: "", dateOfBirth: "", isDependent: true, dependentForInsurance: false, aadhaar: "", nomineeFlag: false, nominationSharePercent: "", guardianName: "" }])}
                    style={{ ...primaryBtn, marginBottom: "14px" }}
                  >
                    <Plus size={15} /> Add family member
                  </button>
                )}
                {(local.family || []).length === 0 && !editing && <p style={{ color: "var(--subtext)", fontSize: "13.5px" }}>No family members recorded.</p>}
                {(local.family || []).map((m, i) => (
                  <RowCard key={i} title={`Member ${i + 1}`}>
                    <Input label="Member name" value={m.memberName} onChange={(v) => setL(`family.${i}.memberName`, v)} />
                    <Input label="Relationship" value={m.relationship} onChange={(v) => setL(`family.${i}.relationship`, v)} />
                    <Input label="Date of birth" type="date" value={m.dateOfBirth || undefined} onChange={(v) => setL(`family.${i}.dateOfBirth`, v)} />
                    <SelectInput label="Dependent" value={String(m.isDependent)} onChange={(v) => setL(`family.${i}.isDependent`, v === "true")} options={["true", "false"]} />
                    <SelectInput label="Nominee" value={String(m.nomineeFlag)} onChange={(v) => setL(`family.${i}.nomineeFlag`, v === "true")} options={["true", "false"]} />
                    <Input label="Nomination %" type="number" value={m.nominationSharePercent || ""} onChange={(v) => setL(`family.${i}.nominationSharePercent`, v === "" ? "" : Number(v))} />
                    <Input label="Guardian name" value={m.guardianName} onChange={(v) => setL(`family.${i}.guardianName`, v)} />
                    {editing && (
                      <button
                        onClick={() => setL("family", (local.family || []).filter((_, idx) => idx !== i))}
                        style={{ ...ghostBtn, alignSelf: "end", color: "var(--red)" }}
                      >
                        <Trash2 size={14} /> Remove
                      </button>
                    )}
                  </RowCard>
                ))}
              </Section>
            </>
          )}

          {activeTab === "qualifications" && (
            <>
              <Section title="Education">
                {editing && (
                  <button
                    onClick={() => setL("education", [...(local.education || []), { highestQualification: "", specialization: "", institution: "", yearOfPassing: "", gradeOrPercentage: "" }])}
                    style={{ ...primaryBtn, marginBottom: "14px" }}
                  >
                    <Plus size={15} /> Add qualification
                  </button>
                )}
                {(local.education || []).length === 0 && !editing && <p style={{ color: "var(--subtext)", fontSize: "13.5px" }}>No education records.</p>}
                {(local.education || []).map((e, i) => (
                  <RowCard key={i} title={`Qualification ${i + 1}`}>
                    <Input label="Highest qualification" value={e.highestQualification} onChange={(v) => setL(`education.${i}.highestQualification`, v)} />
                    <Input label="Specialization" value={e.specialization} onChange={(v) => setL(`education.${i}.specialization`, v)} />
                    <Input label="Institution" value={e.institution} onChange={(v) => setL(`education.${i}.institution`, v)} />
                    <Input label="Passing year" type="number" value={e.yearOfPassing || ""} onChange={(v) => setL(`education.${i}.yearOfPassing`, v === "" ? "" : Number(v))} />
                    <Input label="Grade / percentage" value={e.gradeOrPercentage || ""} onChange={(v) => setL(`education.${i}.gradeOrPercentage`, v)} />
                    {editing && (
                      <button onClick={() => setL("education", (local.education || []).filter((_, idx) => idx !== i))} style={{ ...ghostBtn, alignSelf: "end", color: "var(--red)" }}>
                        <Trash2 size={14} /> Remove
                      </button>
                    )}
                  </RowCard>
                ))}
              </Section>
              <Section title="Skills">
                {editing && (
                  <button
                    onClick={() => setL("skills", [...(local.skills || []), ""])}
                    style={{ ...primaryBtn, marginBottom: "14px" }}
                  >
                    <Plus size={15} /> Add skill
                  </button>
                )}
                <Grid editing={editing}>
                  {(local.skills || []).map((s, i) => (
                    editing ? (
                      <div key={i} style={{ display: "flex", gap: "6px", alignItems: "end" }}>
                        <Input label={`Skill ${i + 1}`} value={s} onChange={(v) => setL(`skills.${i}`, v)} />
                        <button onClick={() => setL("skills", local.skills.filter((_, idx) => idx !== i))} style={{ padding: "9px", background: "var(--background)", border: "1px solid var(--border)", borderRadius: "var(--radius)", cursor: "pointer", color: "var(--red)" }}>
                          <Trash2 size={14} />
                        </button>
                      </div>
                    ) : (
                      <InfoRow key={i} icon={GraduationCap} label={`Skill ${i + 1}`} value={s} />
                    )
                  ))}
                  {(local.skills || []).length === 0 && !editing && <p style={{ color: "var(--subtext)", fontSize: "13.5px" }}>No skills recorded.</p>}
                </Grid>
              </Section>
              <Section title="Previous employment">
                {editing && (
                  <button
                    onClick={() => setL("experience", [...(local.experience || []), { previousEmployerName: "", designation: "", fromDate: "", toDate: "", lastDrawnSalary: "", reasonForLeaving: "", previousPfNumber: "", relievingLetterReceived: false }])}
                    style={{ ...primaryBtn, marginBottom: "14px" }}
                  >
                    <Plus size={15} /> Add experience
                  </button>
                )}
                {(local.experience || []).length === 0 && !editing && <p style={{ color: "var(--subtext)", fontSize: "13.5px" }}>No previous employment recorded.</p>}
                {(local.experience || []).map((e, i) => (
                  <RowCard key={i} title={`Experience ${i + 1}`}>
                    <Input label="Previous employer" value={e.previousEmployerName} onChange={(v) => setL(`experience.${i}.previousEmployerName`, v)} />
                    <Input label="Designation" value={e.designation} onChange={(v) => setL(`experience.${i}.designation`, v)} />
                    <Input label="From" type="date" value={e.fromDate || undefined} onChange={(v) => setL(`experience.${i}.fromDate`, v)} />
                    <Input label="To" type="date" value={e.toDate || undefined} onChange={(v) => setL(`experience.${i}.toDate`, v)} />
                    <Input label="Last drawn salary" type="number" value={e.lastDrawnSalary || ""} onChange={(v) => setL(`experience.${i}.lastDrawnSalary`, v === "" ? "" : Number(v))} />
                    <Input label="Reason for leaving" value={e.reasonForLeaving} onChange={(v) => setL(`experience.${i}.reasonForLeaving`, v)} />
                    {editing && (
                      <button onClick={() => setL("experience", (local.experience || []).filter((_, idx) => idx !== i))} style={{ ...ghostBtn, alignSelf: "end", color: "var(--red)" }}>
                        <Trash2 size={14} /> Remove
                      </button>
                    )}
                  </RowCard>
                ))}
              </Section>
              <Section title="Documents">
                <p style={{ color: "var(--subtext)", fontSize: "13px" }}>
                  Documents captured during registration (uploaded via the wizard) are managed separately in the employee document store.
                </p>
              </Section>
            </>
          )}

          {activeTab === "consents" && (
            <Section title="Access, consent & review">
              <Grid editing={false}>
                <InfoRow icon={LockKeyhole} label="Role" value={local.role || employee.role || "EMPLOYEE"} />
                <InfoRow icon={ClipboardCheck} label="Consents approved" value={`${approvedCount}${consentTotal ? ` of ${consentTotal}` : ""}`} />
              </Grid>
              <div style={{ marginTop: "18px" }}>
                <p style={{ fontSize: "13px", fontWeight: 700, color: "var(--subtext)", textTransform: "uppercase", letterSpacing: "0.4px", marginBottom: "10px" }}>Consent register</p>
                {role === "HR_ADMIN" && (
                  <button
                    onClick={() => setAddConsentOpen(true)}
                    style={{ marginBottom: "12px", display: "inline-flex", alignItems: "center", gap: "6px", padding: "9px 16px", background: "var(--primary)", color: "#fff", border: "none", borderRadius: "var(--radius-sm)", cursor: "pointer", fontWeight: 600, fontSize: "13.5px" }}
                  >
                    <Plus size={16} /> Add consent type
                  </button>
                )}
                {(local.consents || []).length === 0 && <p style={{ color: "var(--subtext)", fontSize: "13.5px" }}>No consent decisions recorded.</p>}
                {local.consents.map((c, i) => (
                  <div key={i} style={{ display: "flex", alignItems: "center", gap: "10px", padding: "12px 14px", border: "1px solid var(--border)", borderRadius: "var(--radius)", marginBottom: "8px", background: "var(--background)" }}>
                    <span style={{ width: "10px", height: "10px", borderRadius: "50%", background: c.status === "GRANTED" ? "var(--green, #16a34a)" : "var(--subtext)" }} />
                    <div style={{ flex: 1 }}>
                      <p style={{ fontSize: "13.5px", fontWeight: 600, color: "var(--text)" }}>{c.code}</p>
                      <p style={{ fontSize: "12px", color: "var(--subtext)" }}>{c.method || "—"}</p>
                    </div>
                    <span style={{ fontSize: "12px", fontWeight: 700, color: c.status === "GRANTED" ? "var(--green, #16a34a)" : "var(--subtext)" }}>{c.status}</span>
                  </div>
                ))}
                {addConsentOpen && (
                  <div style={{ position: "fixed", inset: 0, background: "rgba(15,23,42,0.45)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 50, padding: "20px" }} onClick={() => setAddConsentOpen(false)}>
                    <div style={{ background: "var(--card)", border: "1px solid var(--border)", borderRadius: "18px", padding: "22px", width: "min(460px, 100%)", boxShadow: "0 20px 50px rgba(15,23,42,0.18)" }} onClick={(e) => e.stopPropagation()}>
                      <p style={{ fontSize: "16px", fontWeight: 700, color: "var(--text)", marginBottom: "16px" }}>Add consent type</p>
                      {["code", "title"].map((f) => (
                        <label key={f} style={{ display: "block", marginBottom: "12px" }}>
                          <span style={{ fontSize: "11px", fontWeight: 700, color: "var(--subtext)", textTransform: "uppercase", letterSpacing: "0.4px" }}>{f === "code" ? "Code" : "Title"} *</span>
                          <input
                            value={consentDraft[f]}
                            onChange={(e) => setConsentDraft((p) => ({ ...p, [f]: e.target.value }))}
                            placeholder={f === "code" ? "e.g. EMPLOYEE_DIRECT_DEPOSIT" : "e.g. Direct deposit into personal account"}
                            style={{ width: "100%", marginTop: "5px", padding: "10px 12px", border: "1px solid var(--border)", borderRadius: "10px", fontSize: "14px", color: "var(--text)", background: "var(--background)" }}
                          />
                        </label>
                      ))}
                      <label style={{ display: "block", marginBottom: "12px" }}>
                        <span style={{ fontSize: "11px", fontWeight: 700, color: "var(--subtext)", textTransform: "uppercase", letterSpacing: "0.4px" }}>Legal basis</span>
                        <select value={consentDraft.legalBasis} onChange={(e) => setConsentDraft((p) => ({ ...p, legalBasis: e.target.value }))} style={{ width: "100%", marginTop: "5px", padding: "10px 12px", border: "1px solid var(--border)", borderRadius: "10px", fontSize: "14px", color: "var(--text)", background: "var(--background)" }}>
                          <option value="CONTRACT">Contract</option>
                          <option value="LEGAL_OBLIGATION">Legal obligation</option>
                          <option value="CONSENT">Consent</option>
                          <option value="LEGITIMATE_INTEREST">Legitimate interest</option>
                        </select>
                      </label>
                      <label style={{ display: "flex", alignItems: "center", gap: "8px", marginBottom: "10px", cursor: "pointer" }}>
                        <input type="checkbox" checked={consentDraft.isStatutory} onChange={(e) => setConsentDraft((p) => ({ ...p, isStatutory: e.target.checked }))} />
                        <span style={{ fontSize: "13.5px", color: "var(--text)" }}>Statutory (required even if employee withdraws)</span>
                      </label>
                      <div style={{ display: "flex", gap: "10px", justifyContent: "flex-end", marginTop: "18px" }}>
                        <button onClick={() => setAddConsentOpen(false)} style={{ padding: "9px 16px", border: "1px solid var(--border)", background: "none", borderRadius: "10px", cursor: "pointer", fontWeight: 600, fontSize: "13.5px", color: "var(--subtext)" }}>Cancel</button>
                        <button disabled={creatingConsent || !consentDraft.code || !consentDraft.title} onClick={submitConsentDraft} style={{ padding: "9px 16px", border: "none", background: "var(--primary)", color: "#fff", borderRadius: "10px", cursor: "pointer", fontWeight: 600, fontSize: "13.5px" }}>{creatingConsent ? "Saving…" : "Add consent type"}</button>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            </Section>
          )}

        </div>
      </EditCtx.Provider>
      </div>
      <style>{`
          .ep-field { display: flex; flex-direction: column; gap: 6px; }
          .ep-field span { font-size: 10.5px; font-weight: 700; color: var(--subtext); text-transform: uppercase; letter-spacing: 0.5px; }
          .ep-field input, .ep-field select { padding: 10px 12px; border: 1px solid var(--border); border-radius: 10px; font-size: 14px; color: var(--text); background: var(--card); transition: border-color 0.15s, box-shadow 0.15s; }
          .ep-field input:focus, .ep-field select:focus { outline: none; border-color: var(--primary); box-shadow: 0 0 0 3px rgba(99,102,241,0.14); }
          .ep-field input[readonly], .ep-field select:disabled { border: none; background: transparent; padding: 4px 0; font-size: 14.5px; font-weight: 500; color: var(--text); cursor: default; opacity: 1; appearance: none; }
          .ep-field select:disabled { -webkit-appearance: none; }
          .ep-empty-value { font-size: 14.5px; font-weight: 500; color: var(--subtext); padding: 4px 0; }
        `}</style>
    </MainLayout>
  );
}

const primaryBtn = {
  padding: "9px 16px", background: "var(--primary)", color: "#fff", border: "none",
  borderRadius: "var(--radius-sm)", cursor: "pointer", fontWeight: 600, fontSize: "13.5px",
  display: "inline-flex", alignItems: "center", gap: "6px",
};
const ghostBtn = {
  padding: "9px 16px", background: "none", color: "var(--subtext)", border: "1px solid var(--border)",
  borderRadius: "var(--radius-sm)", cursor: "pointer", fontWeight: 600, fontSize: "13.5px",
  display: "inline-flex", alignItems: "center", gap: "6px",
};

/**
 * Employees Page
 * Module 2 — Employee Management
 * Features: searchable/filterable table, Add Employee modal, status badges,
 *           click-through to employee profile (/employees/:id)
 */

import { useState, useEffect, useCallback, useRef, useMemo } from "react";
import { useNavigate } from "react-router-dom";
import { Plus, Search, Filter, Users, Upload, MoreVertical, Trash2, RotateCcw, CheckCircle2, X, ArrowUpDown, ArrowUp, ArrowDown } from "lucide-react";
import MainLayout from "../../components/layout/MainLayout.jsx";
import PageHeader from "../../components/shared/PageHeader.jsx";
import StatusBadge from "../../components/shared/StatusBadge.jsx";
import Spinner from "../../components/shared/Spinner.jsx";
import EmptyState from "../../components/shared/EmptyState.jsx";
import Modal from "../../components/shared/Modal.jsx";
import ConfirmDialog from "../../components/shared/ConfirmDialog.jsx";
import InitialsAvatar from "../../components/shared/InitialsAvatar.jsx";
import {
  getEmployees,
  createEmployee,
  previewBulkEmployees,
  bulkUploadEmployees,
  undoBulkEmployees,
  deleteEmployee,
} from "../../services/employeeService.js";
import RegistrationWizardModal from "./RegistrationWizardModal.jsx";
import BulkImportPreviewModal from "./BulkImportPreviewModal.jsx";
import { useAuth } from "../../context/AuthContext.jsx";
import { useToast } from "../../context/ToastContext.jsx";
import { getDepartments, getLocations } from "../../services/Orgmanagementservice.js";
import { departments as mockDepartments, locations as mockLocations, employmentTypes, statuses, skillTypes, genders } from "../../mock/employees.js";

const EMPLOYEE_STATUS_META = {
  Active:     { label: "Active",     color: "#16a34a", bg: "#f0fdf4" },
  "On Leave": { label: "On Leave",   color: "#d97706", bg: "#fffbeb" },
  Inactive:   { label: "Inactive",   color: "#64748b", bg: "#f8fafc" },
  Terminated: { label: "Terminated", color: "#dc2626", bg: "#fef2f2" },
};

const dash = (v) => (v === null || v === undefined || String(v).trim() === "" ? "-" : v);

// ─── Add Employee Form ────────────────────────────────────────────────────────
function AddEmployeeModal({ employees, isOpen, onClose, onCreated }) {
  const toast = useToast();
  const [form, setForm] = useState({
    firstName: "", lastName: "", email: "", phone: "", gender: "", dob: "",
    designation: "", skillType: "", department: "", location: "", employmentType: "Full-Time",
    status: "Active", managerId: "", dateOfJoining: new Date().toISOString().slice(0, 10),
    state: "", country: "India", annualSalary: "",
  });
  const [errors, setErrors] = useState({});
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [liveDepartments, setLiveDepartments] = useState([]);
  const [liveLocations, setLiveLocations] = useState([]);

  useEffect(() => {
    if (!isOpen) return;
    getDepartments()
      .then((res) => {
        const depts = res.data || [];
        if (depts.length > 0) {
          setLiveDepartments(depts.map((d) => ({ id: d.id, value: d.id, label: d.name, name: d.name })));
        } else {
          setLiveDepartments(mockDepartments.map((d) => ({ id: d, value: d, label: d, name: d })));
        }
      })
      .catch(() => setLiveDepartments(mockDepartments.map((d) => ({ id: d, value: d, label: d, name: d }))));

    getLocations()
      .then((res) => {
        const locs = res.data || [];
        if (locs.length > 0) {
          setLiveLocations(locs.map((l) => ({ id: l.id, value: l.id, label: l.name, name: l.name })));
        } else {
          setLiveLocations(mockLocations.map((l) => ({ id: l, value: l, label: l, name: l })));
        }
      })
      .catch(() => setLiveLocations(mockLocations.map((l) => ({ id: l, value: l, label: l, name: l }))));
  }, [isOpen]);

  const validate = () => {
    const e = {};
    if (!form.firstName.trim()) e.firstName = "Required";
    if (!form.lastName.trim()) e.lastName = "Required";
    if (!form.email.includes("@")) e.email = "Valid email required";
    if (!form.designation.trim()) e.designation = "Required";
    if (!form.department) e.department = "Required";
    setErrors(e);
    return Object.keys(e).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validate()) return;
    setSaving(true);
    setError("");
    try {
      const selectedDept = liveDepartments.find((d) => d.value === form.department || d.label === form.department);
      const selectedLoc = liveLocations.find((l) => l.value === form.location || l.label === form.location);

      await createEmployee({
        firstName: form.firstName.trim(),
        lastName: form.lastName.trim(),
        email: form.email.trim(),
        phone: form.phone.trim() || undefined,
        gender: form.gender.trim() || undefined,
        dob: form.dob ? String(form.dob).slice(0, 10) : undefined,
        designation: form.designation.trim(),
        skillType: form.skillType || undefined,
        departmentId: selectedDept?.id && selectedDept.id.length > 10 ? selectedDept.id : undefined,
        department: selectedDept?.label || form.department,
        locationId: selectedLoc?.id && selectedLoc.id.length > 10 ? selectedLoc.id : undefined,
        location: selectedLoc?.label || form.location || undefined,
        employmentType: form.employmentType,
        status: form.status,
        managerId: form.managerId || undefined,
        dateOfJoining: form.dateOfJoining ? String(form.dateOfJoining).slice(0, 10) : undefined,
        state: form.state.trim() || undefined,
        country: form.country.trim() || undefined,
        annualSalary: form.annualSalary ? Number(form.annualSalary) : undefined,
      });
      onCreated?.();
      onClose();
      toast("Employee added successfully!");
      setForm({
        firstName: "", lastName: "", email: "", phone: "", gender: "", dob: "",
        designation: "", skillType: "", department: "", location: "", employmentType: "Full-Time",
        status: "Active", managerId: "", dateOfJoining: new Date().toISOString().slice(0, 10),
        state: "", country: "India", annualSalary: "",
      });
    } catch (err) {
      const msg = err?.response?.data?.message || err.message || "Could not add employee";
      setError(msg);
      toast(msg, "error");
    } finally {
      setSaving(false);
    }
  };

  const field = (label, key, type = "text") => (
    <div style={{ display: "flex", flexDirection: "column", gap: "5px" }}>
      <label style={{ fontSize: "12px", fontWeight: 600, color: "var(--label)" }}>{label}</label>
      <input
        type={type}
        value={form[key]}
        onChange={(e) => setForm((p) => ({ ...p, [key]: e.target.value }))}
        style={{
          height: "38px", padding: "0 12px",
          border: `1px solid ${errors[key] ? "var(--red)" : "var(--border)"}`,
          borderRadius: "var(--radius-sm)",
          fontSize: "13.5px", color: "var(--text)", outline: "none",
          transition: "border-color 0.15s",
        }}
        onFocus={(e) => (e.target.style.borderColor = "var(--border-focus)")}
        onBlur={(e) => (e.target.style.borderColor = errors[key] ? "var(--red)" : "var(--border)")}
      />
      {errors[key] && <span style={{ fontSize: "11px", color: "var(--red)" }}>{errors[key]}</span>}
    </div>
  );

  const select = (label, key, options, placeholder) => {
    const items = (options || []).map((o) => (typeof o === "object" && o !== null ? o : { value: o, label: String(o) }));
    return (
      <div style={{ display: "flex", flexDirection: "column", gap: "5px" }}>
        <label style={{ fontSize: "12px", fontWeight: 600, color: "var(--label)" }}>{label}</label>
        <select
          value={form[key]}
          onChange={(e) => setForm((p) => ({ ...p, [key]: e.target.value }))}
          style={{
            height: "38px", padding: "0 12px",
            border: `1px solid ${errors[key] ? "var(--red)" : "var(--border)"}`,
            borderRadius: "var(--radius-sm)",
            fontSize: "13.5px", color: "var(--text)",
            background: "var(--card)", outline: "none",
          }}
        >
          <option value="">{placeholder || `Select ${label.replace(" *", "")}`}</option>
          {items.map((it) => <option key={it.value} value={it.value}>{it.label}</option>)}
        </select>
        {errors[key] && <span style={{ fontSize: "11px", color: "var(--red)" }}>{errors[key]}</span>}
      </div>
    );
  };

  const managerOptions = (employees || [])
    .map((m) => ({ value: m.id, label: `${m.firstName} ${m.lastName} (${m.id})` }));

  const designationOptions = [...new Set([
    "Software Engineer", "Senior Software Engineer", "Tech Lead", "Engineering Manager",
    "Product Manager", "HR Specialist", "HR Manager", "UI/UX Designer", "Accountant", "QA Engineer",
    ...(employees || []).map((e) => e.designation).filter(Boolean),
  ])].sort();

  return (
    <Modal isOpen={isOpen} title="Add New Employee" onClose={onClose}>
      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "14px" }}>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" }}>
          {field("First Name *", "firstName")}
          {field("Last Name *", "lastName")}
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" }}>
          {field("Work Email *", "email", "email")}
          {field("Phone", "phone")}
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" }}>
          {select("Gender", "gender", genders, "Select Gender")}
          {field("Date of Birth", "dob", "date")}
        </div>
        {select("Designation *", "designation", designationOptions, "Select Designation")}
        {select("Skill Type", "skillType", skillTypes, "Select Skill Type")}
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" }}>
          {select("Department *", "department", liveDepartments)}
          {select("Work Location", "location", liveLocations, "Select Work Location")}
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" }}>
          {select("Employment Type", "employmentType", employmentTypes)}
          {select("Status", "status", statuses)}
        </div>
        {select("Reporting Manager", "managerId", managerOptions, "None")}
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" }}>
          {field("Date of Joining", "dateOfJoining", "date")}
          {field("Yearly Salary Package (₹)", "annualSalary", "number")}
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" }}>
          {field("State", "state")}
          {field("Country", "country")}
        </div>

        {error && (
          <div style={{ background: "var(--red-light)", color: "var(--red)", borderRadius: "var(--radius-sm)", padding: "10px 14px", fontSize: "12.5px", fontWeight: 600 }}>
            {error}
          </div>
        )}

        <div style={{ display: "flex", gap: "10px", justifyContent: "flex-end", marginTop: "8px" }}>
          <button type="button" onClick={onClose}
            style={{ padding: "9px 20px", border: "1px solid var(--border)", borderRadius: "var(--radius-sm)", background: "none", color: "var(--label)", fontWeight: 600, fontSize: "13px", cursor: "pointer" }}>
            Cancel
          </button>
          <button type="submit" disabled={saving}
            style={{ padding: "9px 20px", border: "none", borderRadius: "var(--radius-sm)", background: "var(--primary)", color: "#fff", fontWeight: 600, fontSize: "13px", cursor: saving ? "not-allowed" : "pointer", opacity: saving ? 0.7 : 1 }}>
            {saving ? "Creating…" : "Create Employee"}
          </button>
        </div>
      </form>
    </Modal>
  );
}

// ─── Main Page ───────────────────────────────────────────────────────────────
export default function Employees() {
  const navigate = useNavigate();
  const { permissions } = useAuth();
  const canDelete = permissions.includes("employees:delete");
  const showActions = canDelete;
  const toast = useToast();
  const [employees, setEmployees] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [filterDept, setFilterDept] = useState("");
  const [filterStatus, setFilterStatus] = useState("");
  const [filterLocation, setFilterLocation] = useState("");
  const [filterSkill, setFilterSkill] = useState("");
  const [sortField, setSortField] = useState("name");
  const [sortOrder, setSortOrder] = useState("asc");

  const dynamicDepts = useMemo(() => {
    const set = new Set(mockDepartments);
    employees.forEach((e) => {
      if (e.department && e.department.trim()) set.add(e.department.trim());
    });
    return Array.from(set).filter(Boolean);
  }, [employees]);

  const dynamicLocations = useMemo(() => {
    const set = new Set(mockLocations);
    employees.forEach((e) => {
      if (e.location && e.location.trim()) set.add(e.location.trim());
    });
    return Array.from(set).filter(Boolean);
  }, [employees]);

  const dynamicSkills = useMemo(() => {
    const set = new Set(skillTypes);
    employees.forEach((e) => {
      if (e.skillType && e.skillType.trim()) set.add(e.skillType.trim());
    });
    return Array.from(set).filter(Boolean);
  }, [employees]);

  const handleSort = (field) => {
    if (sortField === field) {
      setSortOrder((prev) => (prev === "asc" ? "desc" : "asc"));
    } else {
      setSortField(field);
      setSortOrder("asc");
    }
  };

  const renderSortIcon = (field) => {
    if (sortField !== field) {
      return <ArrowUpDown size={12} style={{ opacity: 0.35 }} />;
    }
    return sortOrder === "asc" ? (
      <ArrowUp size={12} style={{ color: "var(--primary)" }} />
    ) : (
      <ArrowDown size={12} style={{ color: "var(--primary)" }} />
    );
  };

  const getSkillBadge = (skill) => {
    const s = String(skill || "").toLowerCase();
    if (s.includes("highly")) return { bg: "#f5f3ff", color: "#7c3aed", border: "#ddd6fe" };
    if (s.includes("skilled") && !s.includes("semi")) return { bg: "#ecfdf5", color: "#059669", border: "#a7f3d0" };
    if (s.includes("semi")) return { bg: "#eff6ff", color: "#2563eb", border: "#bfdbfe" };
    if (s.includes("unskilled")) return { bg: "#fff7ed", color: "#c2410c", border: "#ffedd5" };
    return { bg: "var(--background)", color: "var(--subtext)", border: "var(--border)" };
  };

  const [showAddModal, setShowAddModal] = useState(false);
  const [showWizard, setShowWizard] = useState(false);
  const [bulkUploading, setBulkUploading] = useState(false);
  const [bulkResult, setBulkResult] = useState(null);
  const [selectedBulkFile, setSelectedBulkFile] = useState(null);
  const [previewData, setPreviewData] = useState(null);
  const [showPreviewModal, setShowPreviewModal] = useState(false);
  const [confirmingImport, setConfirmingImport] = useState(false);
  const [undoBatch, setUndoBatch] = useState(null);
  const [undoing, setUndoing] = useState(false);
  const [menuOpenFor, setMenuOpenFor] = useState(null);
  const [deleteTarget, setDeleteTarget] = useState(null);
  const [deleting, setDeleting] = useState(false);
  const [page, setPage] = useState(1);
  const bulkInputRef = useRef(null);
  const PAGE_SIZE = 10;

  // 15-30s Undo countdown timer
  useEffect(() => {
    if (!undoBatch) return;
    const timer = setInterval(() => {
      setUndoBatch((prev) => {
        if (!prev) return null;
        if (prev.secondsLeft <= 1) return null;
        return { ...prev, secondsLeft: prev.secondsLeft - 1 };
      });
    }, 1000);
    return () => clearInterval(timer);
  }, [undoBatch?.batchId]);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res = await getEmployees({ search, department: filterDept, status: filterStatus });
      setEmployees(res.data);
      setPage(1);
    } finally {
      setLoading(false);
    }
  }, [search, filterDept, filterStatus]);

  useEffect(() => { load(); }, [load]);

  // Close the open row-actions menu when clicking anywhere outside it.
  useEffect(() => {
    const closeMenu = () => setMenuOpenFor(null);
    window.addEventListener("click", closeMenu);
    return () => window.removeEventListener("click", closeMenu);
  }, []);

  const handleDelete = async () => {
    if (!deleteTarget) return;
    setDeleting(true);
    try {
      await deleteEmployee(deleteTarget.id);
      toast(`${deleteTarget.firstName} ${deleteTarget.lastName} (${deleteTarget.id}) permanently deleted`);
      setDeleteTarget(null);
      setMenuOpenFor(null);
      load();
    } catch (err) {
      toast(err?.response?.data?.message || err?.message || "Could not delete employee", "error");
    } finally {
      setDeleting(false);
    }
  };

  const handleBulkFileSelected = async (file) => {
    if (!file) return;
    setBulkUploading(true);
    setBulkResult(null);
    try {
      const formData = new FormData();
      formData.append("file", file);
      const res = await previewBulkEmployees(formData);
      setPreviewData(res.data);
      setSelectedBulkFile(file);
      setShowPreviewModal(true);
    } catch (err) {
      toast(err?.response?.data?.message || err?.message || "Could not parse spreadsheet", "error");
    } finally {
      setBulkUploading(false);
      if (bulkInputRef.current) bulkInputRef.current.value = "";
    }
  };

  const handleConfirmImport = async () => {
    if (!selectedBulkFile) return;
    setConfirmingImport(true);
    try {
      const formData = new FormData();
      formData.append("file", selectedBulkFile);
      const res = await bulkUploadEmployees(formData);
      const result = res.data;

      setShowPreviewModal(false);
      setSelectedBulkFile(null);
      setPreviewData(null);
      load();

      if (result.createdCount > 0) {
        setBulkResult({
          createdCount: result.createdCount,
          skippedCount: result.skippedCount,
          skippedDuplicatesCount: result.skippedDuplicatesCount,
          skipped: result.skipped || [],
        });
        toast(`Successfully imported ${result.createdCount} employee${result.createdCount !== 1 ? "s" : ""}${result.skippedDuplicatesCount ? ` (${result.skippedDuplicatesCount} duplicate${result.skippedDuplicatesCount !== 1 ? "s" : ""} skipped)` : ""}`);

        if (result.batchId) {
          setUndoBatch({
            batchId: result.batchId,
            count: result.createdCount,
            skippedCount: result.skippedDuplicatesCount || 0,
            secondsLeft: 30,
          });
        }
      } else if (result.isAllDuplicates || result.skippedDuplicatesCount > 0) {
        toast(`Data is already present: all ${result.skippedDuplicatesCount} record(s) already exist in the system.`, "info");
      } else {
        toast("No valid new records were imported.", "warning");
      }
    } catch (err) {
      toast(err?.response?.data?.message || err?.message || "Could not import employees", "error");
    } finally {
      setConfirmingImport(false);
    }
  };

  const handleUndoImport = async () => {
    if (!undoBatch?.batchId || undoing) return;
    setUndoing(true);
    try {
      await undoBulkEmployees(undoBatch.batchId);
      toast(`Import undone: ${undoBatch.count} employee record${undoBatch.count !== 1 ? "s" : ""} removed`);
      setUndoBatch(null);
      setBulkResult(null);
      load();
    } catch (err) {
      toast(err?.response?.data?.message || err?.message || "Could not undo import", "error");
    } finally {
      setUndoing(false);
    }
  };

  const processedEmployees = useMemo(() => {
    let list = [...employees];

    if (filterLocation) {
      list = list.filter((e) => String(e.location || "").toLowerCase() === filterLocation.toLowerCase());
    }
    if (filterSkill) {
      list = list.filter((e) => String(e.skillType || "").toLowerCase() === filterSkill.toLowerCase());
    }

    list.sort((a, b) => {
      let valA = "";
      let valB = "";
      if (sortField === "name") {
        valA = `${a.firstName || ""} ${a.lastName || ""}`.toLowerCase();
        valB = `${b.firstName || ""} ${b.lastName || ""}`.toLowerCase();
      } else if (sortField === "designation") {
        valA = String(a.designation || "").toLowerCase();
        valB = String(b.designation || "").toLowerCase();
      } else if (sortField === "department") {
        valA = String(a.department || "").toLowerCase();
        valB = String(b.department || "").toLowerCase();
      } else if (sortField === "location") {
        valA = String(a.location || "").toLowerCase();
        valB = String(b.location || "").toLowerCase();
      } else if (sortField === "skillType") {
        valA = String(a.skillType || "").toLowerCase();
        valB = String(b.skillType || "").toLowerCase();
      } else if (sortField === "type") {
        valA = String(a.employmentType || "").toLowerCase();
        valB = String(b.employmentType || "").toLowerCase();
      } else if (sortField === "status") {
        valA = String(a.status || "").toLowerCase();
        valB = String(b.status || "").toLowerCase();
      } else if (sortField === "dateOfJoining") {
        valA = new Date(a.dateOfJoining || a.joinDate || 0).getTime();
        valB = new Date(b.dateOfJoining || b.joinDate || 0).getTime();
      }

      if (valA < valB) return sortOrder === "asc" ? -1 : 1;
      if (valA > valB) return sortOrder === "asc" ? 1 : -1;
      return 0;
    });

    return list;
  }, [employees, filterLocation, filterSkill, sortField, sortOrder]);

  const totalPages = Math.ceil(processedEmployees.length / PAGE_SIZE);
  const paginated  = processedEmployees.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  return (
    <MainLayout>
      <div style={{ maxWidth: "1480px", margin: "0 auto" }}>
        <PageHeader
          title="Employees"
          subtitle={`${processedEmployees.length} employee${processedEmployees.length !== 1 ? "s" : ""} found`}
        >
          <div style={{ display: "flex", gap: "10px", alignItems: "center" }}>
            <button
              id="bulk-upload-btn"
              onClick={() => bulkInputRef.current?.click()}
              disabled={bulkUploading}
              title="Import 100+ employees from a spreadsheet (.xlsx, .csv, .tsv). Rows missing mandatory fields are skipped."
              style={{
                display: "flex", alignItems: "center", gap: "6px",
                padding: "9px 16px", background: "var(--card)", color: "var(--text)",
                border: "1px solid var(--border)", borderRadius: "var(--radius-sm)",
                fontWeight: 600, fontSize: "13px", cursor: bulkUploading ? "wait" : "pointer",
                transition: "all 0.15s",
              }}
              onMouseEnter={(e) => (e.currentTarget.style.borderColor = "var(--primary)")}
              onMouseLeave={(e) => (e.currentTarget.style.borderColor = "var(--border)")}
            >
              <Upload size={16} /> {bulkUploading ? "Uploading…" : "Bulk Upload/Import"}
            </button>
            <input
              ref={bulkInputRef}
              type="file"
              accept=".xlsx,.xlsm,.xls,.csv,.tsv,.txt"
              style={{ display: "none" }}
              onChange={(e) => handleBulkFileSelected(e.target.files?.[0])}
            />
            <button
              id="add-employee-btn"
              onClick={() => setShowAddModal(true)}
              style={{
                display: "flex", alignItems: "center", gap: "6px",
                padding: "9px 16px", background: "var(--primary)", color: "#fff",
                border: "none", borderRadius: "var(--radius-sm)",
                fontWeight: 600, fontSize: "13px", cursor: "pointer",
                transition: "background 0.15s",
              }}
              onMouseEnter={(e) => (e.currentTarget.style.background = "var(--primary-hover)")}
              onMouseLeave={(e) => (e.currentTarget.style.background = "var(--primary)")}
            >
              <Plus size={16} /> Add Employee
            </button>
          </div>
        </PageHeader>

        {bulkResult && (
          <div
            style={{
              background: "var(--card)", border: "1px solid var(--border)",
              borderRadius: "var(--radius-lg)", padding: "14px 18px", marginBottom: "16px",
            }}
          >
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: "12px", flexWrap: "wrap" }}>
              <div style={{ display: "flex", gap: "18px", alignItems: "center" }}>
                <span style={{ fontSize: "13.5px", fontWeight: 700, color: "#16a34a" }}>
                  {bulkResult.createdCount} imported
                </span>
                <span style={{ fontSize: "13.5px", fontWeight: 700, color: bulkResult.skippedCount ? "#d97706" : "var(--subtext)" }}>
                  {bulkResult.skippedCount} skipped
                </span>
              </div>
              <button
                onClick={() => setBulkResult(null)}
                style={{ background: "none", border: "none", color: "var(--subtext)", cursor: "pointer", fontSize: "12.5px", fontWeight: 600 }}
              >
                Dismiss
              </button>
            </div>
            {bulkResult.skipped.length > 0 && (
              <div style={{ marginTop: "8px", maxHeight: "120px", overflowY: "auto" }}>
                {bulkResult.skipped.slice(0, 25).map((s, i) => (
                  <div key={i} style={{ fontSize: "12px", color: "var(--subtext)", padding: "3px 0" }}>
                    Row {s.row}: {s.reason}
                  </div>
                ))}
                {bulkResult.skipped.length > 25 && (
                  <div style={{ fontSize: "12px", color: "var(--subtext)" }}>
                    … and {bulkResult.skipped.length - 25} more
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {/* Filters */}
        <div
          style={{
            display: "flex", gap: "10px", marginBottom: "20px",
            flexWrap: "wrap", alignItems: "center",
          }}
        >
          <div style={{ position: "relative", flex: "1 1 220px", maxWidth: "300px" }}>
            <Search size={15} style={{ position: "absolute", left: "12px", top: "50%", transform: "translateY(-50%)", color: "var(--subtext)", pointerEvents: "none" }} />
            <input
              id="employee-search"
              type="text"
              placeholder="Search by name, email, ID…"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              style={{
                width: "100%", height: "36px",
                paddingLeft: "36px", paddingRight: "12px",
                border: "1px solid var(--border)", borderRadius: "var(--radius-sm)",
                fontSize: "13px", color: "var(--text)", outline: "none",
                background: "var(--card)", transition: "border-color 0.15s",
              }}
              onFocus={(e) => (e.target.style.borderColor = "var(--border-focus)")}
              onBlur={(e) => (e.target.style.borderColor = "var(--border)")}
            />
          </div>

          <div style={{ display: "flex", alignItems: "center", gap: "5px" }}>
            <Filter size={15} style={{ color: "var(--subtext)" }} />
            <span style={{ fontSize: "12px", fontWeight: 600, color: "var(--subtext)" }}>Filters:</span>
          </div>

          <select
            id="filter-department"
            value={filterDept}
            onChange={(e) => setFilterDept(e.target.value)}
            style={{ height: "36px", padding: "0 10px", border: "1px solid var(--border)", borderRadius: "var(--radius-sm)", fontSize: "12.5px", color: "var(--text)", background: "var(--card)", outline: "none", cursor: "pointer" }}
          >
            <option value="">All Departments</option>
            {dynamicDepts.map((d) => <option key={d} value={d}>{d}</option>)}
          </select>

          <select
            id="filter-location"
            value={filterLocation}
            onChange={(e) => setFilterLocation(e.target.value)}
            style={{ height: "36px", padding: "0 10px", border: "1px solid var(--border)", borderRadius: "var(--radius-sm)", fontSize: "12.5px", color: "var(--text)", background: "var(--card)", outline: "none", cursor: "pointer" }}
          >
            <option value="">All Locations</option>
            {dynamicLocations.map((l) => <option key={l} value={l}>{l}</option>)}
          </select>

          <select
            id="filter-skill"
            value={filterSkill}
            onChange={(e) => setFilterSkill(e.target.value)}
            style={{ height: "36px", padding: "0 10px", border: "1px solid var(--border)", borderRadius: "var(--radius-sm)", fontSize: "12.5px", color: "var(--text)", background: "var(--card)", outline: "none", cursor: "pointer" }}
          >
            <option value="">All Skill Tiers</option>
            {dynamicSkills.map((s) => <option key={s} value={s}>{s}</option>)}
          </select>

          <select
            id="filter-status"
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value)}
            style={{ height: "36px", padding: "0 10px", border: "1px solid var(--border)", borderRadius: "var(--radius-sm)", fontSize: "12.5px", color: "var(--text)", background: "var(--card)", outline: "none", cursor: "pointer" }}
          >
            <option value="">All Statuses</option>
            {statuses.map((s) => <option key={s} value={s}>{s}</option>)}
          </select>

          {(search || filterDept || filterLocation || filterSkill || filterStatus) && (
            <button
              onClick={() => {
                setSearch("");
                setFilterDept("");
                setFilterLocation("");
                setFilterSkill("");
                setFilterStatus("");
              }}
              style={{
                height: "36px",
                padding: "0 12px",
                background: "var(--background)",
                border: "1px solid var(--border)",
                borderRadius: "var(--radius-sm)",
                fontSize: "12px",
                fontWeight: 600,
                color: "var(--subtext)",
                cursor: "pointer",
                display: "inline-flex",
                alignItems: "center",
                gap: "4px",
              }}
            >
              <X size={13} /> Reset
            </button>
          )}
        </div>

        {/* Table */}
        <div
          style={{
            background: "var(--card)",
            borderRadius: "var(--radius-lg)",
            border: "1px solid var(--border)",
            boxShadow: "var(--shadow-sm)",
            overflow: "hidden",
          }}
        >
          {loading ? (
            <Spinner />
          ) : paginated.length === 0 ? (
            <EmptyState
              icon={Users}
              title="No employees found"
              subtitle="Try adjusting your search or filter criteria."
            />
          ) : (
            <div style={{ overflowX: "auto" }}>
              <table style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead>
                  <tr style={{ background: "var(--background)", borderBottom: "1px solid var(--border)" }}>
                    <th
                      onClick={() => handleSort("name")}
                      style={{ padding: "11px 16px", textAlign: "left", fontSize: "11px", fontWeight: 700, color: "var(--subtext)", textTransform: "uppercase", letterSpacing: "0.5px", cursor: "pointer", userSelect: "none" }}
                    >
                      <div style={{ display: "inline-flex", alignItems: "center", gap: "5px" }}>
                        Employee {renderSortIcon("name")}
                      </div>
                    </th>
                    <th
                      onClick={() => handleSort("designation")}
                      style={{ padding: "11px 16px", textAlign: "left", fontSize: "11px", fontWeight: 700, color: "var(--subtext)", textTransform: "uppercase", letterSpacing: "0.5px", cursor: "pointer", userSelect: "none" }}
                    >
                      <div style={{ display: "inline-flex", alignItems: "center", gap: "5px" }}>
                        Designation {renderSortIcon("designation")}
                      </div>
                    </th>
                    <th
                      onClick={() => handleSort("department")}
                      style={{ padding: "11px 16px", textAlign: "left", fontSize: "11px", fontWeight: 700, color: "var(--subtext)", textTransform: "uppercase", letterSpacing: "0.5px", cursor: "pointer", userSelect: "none" }}
                    >
                      <div style={{ display: "inline-flex", alignItems: "center", gap: "5px" }}>
                        Department {renderSortIcon("department")}
                      </div>
                    </th>
                    <th
                      onClick={() => handleSort("location")}
                      style={{ padding: "11px 16px", textAlign: "left", fontSize: "11px", fontWeight: 700, color: "var(--subtext)", textTransform: "uppercase", letterSpacing: "0.5px", cursor: "pointer", userSelect: "none" }}
                    >
                      <div style={{ display: "inline-flex", alignItems: "center", gap: "5px" }}>
                        Work Location {renderSortIcon("location")}
                      </div>
                    </th>
                    <th
                      onClick={() => handleSort("skillType")}
                      style={{ padding: "11px 16px", textAlign: "left", fontSize: "11px", fontWeight: 700, color: "var(--subtext)", textTransform: "uppercase", letterSpacing: "0.5px", cursor: "pointer", userSelect: "none" }}
                    >
                      <div style={{ display: "inline-flex", alignItems: "center", gap: "5px" }}>
                        Skill Tier {renderSortIcon("skillType")}
                      </div>
                    </th>
                    <th
                      onClick={() => handleSort("type")}
                      style={{ padding: "11px 16px", textAlign: "left", fontSize: "11px", fontWeight: 700, color: "var(--subtext)", textTransform: "uppercase", letterSpacing: "0.5px", cursor: "pointer", userSelect: "none" }}
                    >
                      <div style={{ display: "inline-flex", alignItems: "center", gap: "5px" }}>
                        Type {renderSortIcon("type")}
                      </div>
                    </th>
                    <th
                      onClick={() => handleSort("status")}
                      style={{ padding: "11px 16px", textAlign: "left", fontSize: "11px", fontWeight: 700, color: "var(--subtext)", textTransform: "uppercase", letterSpacing: "0.5px", cursor: "pointer", userSelect: "none" }}
                    >
                      <div style={{ display: "inline-flex", alignItems: "center", gap: "5px" }}>
                        Status {renderSortIcon("status")}
                      </div>
                    </th>
                    <th
                      onClick={() => handleSort("dateOfJoining")}
                      style={{ padding: "11px 16px", textAlign: "left", fontSize: "11px", fontWeight: 700, color: "var(--subtext)", textTransform: "uppercase", letterSpacing: "0.5px", cursor: "pointer", userSelect: "none" }}
                    >
                      <div style={{ display: "inline-flex", alignItems: "center", gap: "5px" }}>
                        Joined {renderSortIcon("dateOfJoining")}
                      </div>
                    </th>
                    {showActions && (
                      <th style={{ padding: "11px 16px", textAlign: "right", fontSize: "11px", fontWeight: 700, color: "var(--subtext)", textTransform: "uppercase", letterSpacing: "0.5px" }}>
                        Actions
                      </th>
                    )}
                  </tr>
                </thead>
                <tbody>
                  {paginated.map((emp, i) => (
                    <tr
                      key={emp.id}
                      onClick={() => navigate(`/employees/${emp.id}`)}
                      style={{
                        borderBottom: i < paginated.length - 1 ? "1px solid var(--border)" : "none",
                        cursor: "pointer",
                        transition: "background 0.12s",
                      }}
                      onMouseEnter={(e) => (e.currentTarget.style.background = "var(--background)")}
                      onMouseLeave={(e) => (e.currentTarget.style.background = "none")}
                    >
                      {/* Employee cell */}
                      <td style={{ padding: "14px 16px" }}>
                        <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
                          <InitialsAvatar firstName={emp.firstName} lastName={emp.lastName} size={34} />
                          <div>
                            <p style={{ fontWeight: 600, fontSize: "13.5px", color: "var(--text)", lineHeight: 1.3 }}>
                              {emp.firstName} {emp.lastName}
                            </p>
                            <p style={{ fontSize: "11.5px", color: "var(--subtext)" }}>{emp.id}</p>
                          </div>
                        </div>
                      </td>
                      <td style={{ padding: "14px 16px", fontSize: "13.5px", color: "var(--text)" }}>{dash(emp.designation)}</td>
                      <td style={{ padding: "14px 16px", fontSize: "13.5px", color: "var(--label)" }}>{dash(emp.department)}</td>
                      <td style={{ padding: "14px 16px", fontSize: "13.5px", color: "var(--label)" }}>{dash(emp.location)}</td>
                      <td style={{ padding: "14px 16px" }}>
                        <span
                          style={{
                            fontSize: "11.5px",
                            fontWeight: 600,
                            padding: "2px 8px",
                            borderRadius: "99px",
                            background: getSkillBadge(emp.skillType).bg,
                            color: getSkillBadge(emp.skillType).color,
                            border: `1px solid ${getSkillBadge(emp.skillType).border}`,
                          }}
                        >
                          {dash(emp.skillType || "General")}
                        </span>
                      </td>
                      <td style={{ padding: "14px 16px" }}>
                        <span style={{ fontSize: "11.5px", color: emp.employmentType === "Contract" ? "var(--amber)" : "var(--label)", background: emp.employmentType === "Contract" ? "var(--amber-light)" : "var(--background)", padding: "2px 8px", borderRadius: "99px", fontWeight: 500 }}>
                          {dash(emp.employmentType)}
                        </span>
                      </td>
                      <td style={{ padding: "14px 16px" }}>
                        <StatusBadge {...(EMPLOYEE_STATUS_META[emp.status] || EMPLOYEE_STATUS_META.Active)} />
                      </td>
                      <td style={{ padding: "14px 16px", fontSize: "12.5px", color: "var(--subtext)", whiteSpace: "nowrap" }}>
                        {emp.dateOfJoining || emp.joinDate ? new Date(emp.dateOfJoining || emp.joinDate).toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" }) : "-"}
                      </td>
{showActions && (
                        <td style={{ padding: "14px 16px", textAlign: "right" }} onClick={(e) => e.stopPropagation()}>
                          <div style={{ position: "relative", display: "inline-block" }}>
                            <button
                              aria-label="Row actions"
                              onClick={() => setMenuOpenFor((cur) => (cur === emp.id ? null : emp.id))}
                              style={{
                                width: "32px", height: "32px", borderRadius: "var(--radius-sm)",
                                border: "1px solid var(--border)",
                                background: menuOpenFor === emp.id ? "var(--background)" : "none",
                                color: "var(--label)", cursor: "pointer",
                                display: "grid", placeItems: "center",
                                transition: "all 0.15s",
                              }}
                              onMouseEnter={(e) => { e.currentTarget.style.borderColor = "var(--primary)"; e.currentTarget.style.color = "var(--primary)"; }}
                              onMouseLeave={(e) => { if (menuOpenFor !== emp.id) { e.currentTarget.style.borderColor = "var(--border)"; e.currentTarget.style.color = "var(--label)"; } }}
                            >
                              <MoreVertical size={16} />
                            </button>

                            {menuOpenFor === emp.id && (
                              <div
                                style={{
                                  position: "absolute", right: 0, top: "38px", zIndex: 20,
                                  background: "var(--card)", border: "1px solid var(--border)",
                                  borderRadius: "var(--radius-md)", boxShadow: "0 8px 24px rgba(15,23,42,0.14)",
                                  minWidth: "168px", overflow: "hidden", padding: "6px",
                                }}
                              >
                                {canDelete && (
                                  <button
                                    onClick={() => { setMenuOpenFor(null); setDeleteTarget(emp); }}
                                    style={{
                                      display: "flex", alignItems: "center", gap: "9px", width: "100%",
                                      padding: "9px 12px", border: "none", background: "none",
                                      color: "var(--red)", fontSize: "13px", fontWeight: 500,
                                      cursor: "pointer", textAlign: "left", borderRadius: "var(--radius-sm)",
                                      transition: "background 0.12s",
                                    }}
                                    onMouseEnter={(e) => (e.currentTarget.style.background = "var(--red-light)")}
                                    onMouseLeave={(e) => (e.currentTarget.style.background = "none")}
                                  >
                                    <Trash2 size={14} /> Delete Employee
                                  </button>
                                )}
                              </div>
                            )}
                          </div>
                        </td>
                      )}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* Pagination */}
          {!loading && processedEmployees.length > PAGE_SIZE && (
            <div
              style={{
                display: "flex", alignItems: "center", justifyContent: "space-between",
                padding: "12px 20px", borderTop: "1px solid var(--border)",
              }}
            >
              <span style={{ fontSize: "12.5px", color: "var(--subtext)" }}>
                Showing {(page - 1) * PAGE_SIZE + 1}–{Math.min(page * PAGE_SIZE, processedEmployees.length)} of {processedEmployees.length}
              </span>
              <div style={{ display: "flex", gap: "6px" }}>
                {Array.from({ length: totalPages }, (_, i) => i + 1).map((p) => (
                  <button
                    key={p}
                    onClick={() => setPage(p)}
                    style={{
                      width: "30px", height: "30px",
                      border: p === page ? "none" : "1px solid var(--border)",
                      borderRadius: "var(--radius-sm)",
                      background: p === page ? "var(--primary)" : "none",
                      color: p === page ? "#fff" : "var(--label)",
                      fontWeight: p === page ? 700 : 400,
                      fontSize: "13px", cursor: "pointer",
                      transition: "background 0.15s",
                    }}
                  >
                    {p}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      <BulkImportPreviewModal
        isOpen={showPreviewModal}
        onClose={() => {
          if (!confirmingImport) {
            setShowPreviewModal(false);
            setSelectedBulkFile(null);
            setPreviewData(null);
          }
        }}
        fileName={selectedBulkFile?.name}
        previewData={previewData}
        onConfirm={handleConfirmImport}
        confirming={confirmingImport}
      />

      {/* Floating 15-30s Undo Banner */}
      {undoBatch && (
        <div
          id="bulk-import-undo-banner"
          style={{
            position: "fixed",
            bottom: "24px",
            left: "50%",
            transform: "translateX(-50%)",
            zIndex: 1000,
            background: "var(--card)",
            border: "1px solid rgba(16, 185, 129, 0.4)",
            boxShadow: "0 10px 30px rgba(0,0,0,0.2), 0 0 15px rgba(16, 185, 129, 0.15)",
            borderRadius: "14px",
            padding: "12px 18px",
            display: "flex",
            alignItems: "center",
            gap: "16px",
            animation: "fadeInUp 0.25s ease-out",
            maxWidth: "92vw",
          }}
        >
          <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
            <div
              style={{
                width: "30px", height: "30px", borderRadius: "50%",
                background: "rgba(34, 197, 94, 0.15)", color: "#16a34a",
                display: "flex", alignItems: "center", justifyContent: "center",
                flexShrink: 0,
              }}
            >
              <CheckCircle2 size={18} />
            </div>
            <div>
              <div style={{ fontSize: "13px", fontWeight: 700, color: "var(--text)" }}>
                Imported {undoBatch.count} employee{undoBatch.count !== 1 ? "s" : ""}
              </div>
              <div style={{ fontSize: "11.5px", color: "var(--subtext)" }}>
                {undoBatch.skippedCount > 0 ? `${undoBatch.skippedCount} duplicate(s) skipped · ` : ""}
                Undo window expires in {undoBatch.secondsLeft}s
              </div>
            </div>
          </div>

          <button
            id="bulk-import-undo-btn"
            type="button"
            disabled={undoing}
            onClick={handleUndoImport}
            style={{
              display: "flex", alignItems: "center", gap: "6px",
              padding: "7px 14px", borderRadius: "8px",
              background: "rgba(239, 68, 68, 0.1)", color: "#dc2626",
              border: "1px solid rgba(239, 68, 68, 0.3)",
              fontSize: "12.5px", fontWeight: 700,
              cursor: undoing ? "wait" : "pointer",
              transition: "all 0.15s",
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.background = "#dc2626";
              e.currentTarget.style.color = "#ffffff";
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.background = "rgba(239, 68, 68, 0.1)";
              e.currentTarget.style.color = "#dc2626";
            }}
          >
            <RotateCcw size={14} style={{ animation: undoing ? "spin 1s linear infinite" : "none" }} />
            {undoing ? "Undoing…" : `Undo Import (${undoBatch.secondsLeft}s)`}
          </button>

          <button
            type="button"
            onClick={() => setUndoBatch(null)}
            title="Dismiss undo"
            style={{
              background: "none", border: "none", color: "var(--subtext)",
              cursor: "pointer", padding: "4px", display: "flex", alignItems: "center",
            }}
          >
            <X size={15} />
          </button>
        </div>
      )}

      <AddEmployeeModal isOpen={showAddModal} employees={employees} onClose={() => setShowAddModal(false)} onCreated={load} />
      <RegistrationWizardModal
        isOpen={showWizard}
        onClose={() => setShowWizard(false)}
        onRegistered={load}
        onSwitchToStandard={() => setShowAddModal(true)}
      />
      <ConfirmDialog
        isOpen={!!deleteTarget}
        title="Delete employee"
        message={`Permanently delete ${deleteTarget?.firstName} ${deleteTarget?.lastName} (${deleteTarget?.id})? This removes the employee and all their records — attendance, leave, payroll, reviews and more — and can't be undone.`}
        confirmLabel={deleting ? "Deleting…" : "Delete employee"}
        cancelLabel="Cancel"
        danger
        onConfirm={handleDelete}
        onCancel={() => setDeleteTarget(null)}
      />
    </MainLayout>
  );
}

