                    setLeaveTypeFilter(e.target.value);
                    setCurrentPage(1);
                  }}
                >
                  <option value="">All Leave Types</option>
                  {leaveTypes.map((lt) => (
                    <option key={lt.id} value={lt.id}>{lt.name}</option>
