                    <option key={s} value={s}>{s}</option>
                  ))}
                </select>

                <div className="leave-date-pill-group">
                  <label>From</label>
                  <input
                    type="date"
                    className="leave-date-input"
                    value={dateRangeFilter.startDate}
                    onChange={(e) => {
                      setDateRangeFilter((p) => ({ ...p, startDate: e.target.value }));
                      setCurrentPage(1);
                    }}
                  />
                  <label>To</label>
                  <input
                    type="date"
