            {(showEmployee ? ["Employee", "Cycle", "Self Rating", "Manager Rating", "Final Rating", "Increment", "Promotion", "Released"] : ["Cycle", "Self Rating", "Manager Rating", "Final Rating", "Increment", "Promotion", "Released"]).map((heading) => (
