  onClose,
  detail,
  loading,
}) {
  if (!isOpen) return null;

  return (
    <Modal
      isOpen={isOpen}
      title="Employee Performance Details"
      onClose={onClose}
    >
      {loading ? (
        <Spinner />
      ) : !detail ? (
        <EmptyState
          icon={Users}
          title="No employee details"
          subtitle="Performance details could not be loaded."
        />
      ) : (
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "18px",
          }}
        >
          <div>
            <h3
              style={{
                fontSize: "16px",
                fontWeight: 700,
                color: "var(--text)",
                marginBottom: "4px",
              }}
            >
              {detail.employee.name}
            </h3>

            <p
              style={{
                fontSize: "12px",
                color: "var(--subtext)",
              }}
            >
              {detail.employee.employeeId} · {detail.cycle.name}
